package coreapi

import (
	"context"
	"log/slog"
	"net/http"
	"net/url"

	"github.com/danielgtaylor/huma/v2"
	"github.com/google/uuid"

	"entire.io/api/corev1"
	"entire.io/core/api"
	"entire.io/core/mirrorrepo"
	"entire.io/core/mirrorrequest"
	"entire.io/core/repodirectory"
	"entire.io/slogutil"
)

// MirrorRequestService backs /api/v1/mirror-requests.
type MirrorRequestService struct {
	Server *api.Server
}

// CreateMirrorRequest accepts a mirror placement request for asynchronous processing.
func (s *MirrorRequestService) CreateMirrorRequest(ctx context.Context, in *corev1.CreateMirrorRequestInput) (*corev1.CreateMirrorRequestOutput, error) {
	claims := api.ClaimsFromContext(ctx)
	if claims == nil {
		return nil, unauthorized("authentication required")
	}
	result, err := s.Server.SubmitMirrorRequest(ctx, claims, in.Body.Provider, in.Body.Owner, in.Body.Repo, in.Body.ClusterHost)
	if err != nil {
		return nil, mapOpError(err)
	}
	out := acceptedMirrorRequestResponse(result)
	return &out, nil
}

// GetMirrorRequest returns a request only to its submitting account.
func (s *MirrorRequestService) GetMirrorRequest(ctx context.Context, in *corev1.GetMirrorRequestInput) (*corev1.GetMirrorRequestOutput, error) {
	claims := api.ClaimsFromContext(ctx)
	if claims == nil {
		return nil, unauthorized("authentication required")
	}
	requestID, err := uuid.Parse(in.RequestID)
	if err != nil {
		return nil, badRequest("invalid mirror request id")
	}
	request, err := s.Server.GetMirrorRequest(ctx, claims, requestID)
	if err != nil {
		return nil, mapOpError(err)
	}
	body, err := s.statusBody(ctx, request)
	if err != nil {
		return nil, err
	}
	return &corev1.GetMirrorRequestOutput{Body: body}, nil
}

func acceptedMirrorRequestResponse(result mirrorrequest.CreateResult) corev1.CreateMirrorRequestOutput {
	return corev1.CreateMirrorRequestOutput{
		Status:   http.StatusAccepted,
		Location: apiBasePrefix + "/mirror-requests/" + result.Request.ID.String(),
		Body: corev1.MirrorRequest{
			RequestID: result.Request.ID.String(),
			Status:    string(result.Request.Status),
		},
	}
}

func (s *MirrorRequestService) statusBody(ctx context.Context, request mirrorrequest.Request) (corev1.MirrorRequest, error) {
	body := corev1.MirrorRequest{RequestID: request.ID.String(), Status: string(request.Status)}
	switch request.Status {
	case mirrorrequest.StatusPending, mirrorrequest.StatusProcessing:
		return body, nil
	case mirrorrequest.StatusSucceeded:
		if request.MirrorID == nil {
			slogutil.Error(ctx, "succeeded mirror request has no mirror ID", slog.String("request_id", request.ID.String()))
			return corev1.MirrorRequest{}, internalErr()
		}
		host, err := s.Server.ClusterPublicHost(ctx, request.ClusterSlug)
		if err != nil || host == "" {
			slogutil.Error(ctx, "resolve mirror request cluster host", slog.String("request_id", request.ID.String()), slog.Any("error", err))
			return corev1.MirrorRequest{}, internalErr()
		}
