	"github.com/entirehq/entiredb/modules/jwtverify"
	"github.com/entirehq/entiredb/modules/ratelimit"
)

// RepoBridge is the subset of core/repoadmin.Client used by the admin
// handlers and the provisioning reconciler — the control-plane bridge
// to entiredb. Interface-typed so the api package doesn't import
// repoadmin just for construction.
//
// clusterSlug names the destination entiredb cluster within this
// regional core's jurisdiction; the implementation routes the RPC to
// that cluster's :8281 listener. Required and must match a known
// cluster — the production wiring (repoadmin.Router) rejects unknown
// slugs with ErrUnknownCluster rather than falling back to a default.
type RepoBridge interface {
	Provision(ctx context.Context, repoID model.RepoID, clusterSlug, url, mirrorUpstreamURL string, mirrorAppInstallationID int64, objectFormat, repoGroupID, defaultBranch, nativeMirrorPrimaryURL, trustLifecycle string) error
	Delete(ctx context.Context, repoID model.RepoID, clusterSlug string) error
	MarkMirrorInitialSyncDone(ctx context.Context, repoID model.RepoID, clusterSlug string) error
	// GetTrustState reads a placement's current trust view from the data plane.
	// The native-mirror rooted-expansion capability fence
	// (ADR 20260724-rsl-root-of-trust-mvp) uses it to refuse expanding a repo
	// that has already rooted.
	GetTrustState(ctx context.Context, repoID model.RepoID, clusterSlug string) (repoadmin.TrustState, error)
}

// TrustReader reads read-only RSL trust state from the data plane for the
// admin trust card, dispatched by cluster slug. The production implementation
// is *repoadmin.Router; nil means no data-plane bridge is wired, so every
// trust read is reported as "status unavailable" rather than failing. Kept
// separate from RepoBridge so an older bridge that predates trust still
// satisfies RepoBridge without pretending to answer trust reads.
type TrustReader interface {
	GetTrustState(ctx context.Context, repoID model.RepoID, clusterSlug string) (repoadmin.TrustState, error)
	// ValidateTrustPublication runs the data plane's diagnostic publication
	// preflight, which reports the visible-ref inventory, estimated baseline,
	// workload class, and oversized classification. A passing result is never an
	// authorization to publish.
	ValidateTrustPublication(ctx context.Context, repoID model.RepoID, clusterSlug string, preflight repoadmin.TrustPreflight) (repoadmin.TrustPreflightResult, error)
	// GetTrustReceipt reads the durable publication receipt for (repo, operation),
	// whose verification baseline the card renders as the history boundary.
	GetTrustReceipt(ctx context.Context, repoID model.RepoID, clusterSlug, operationID string) (repoadmin.TrustReceipt, error)
	// GetTrustActivity reads a page of the repo's RSL reference entries (newest
	// first) for the admin console's recent-activity view.
	GetTrustActivity(ctx context.Context, repoID model.RepoID, clusterSlug string, pageSize int32, cursor string) (repoadmin.TrustActivityPage, error)
}

// TrustEnabler records a bootstrap trust intent for a repo and drives one
// reconcile pass to publish it (ADR 20260724-rsl-root-of-trust-mvp, slice 2).
// The production implementation lives in internal/entirecore, wiring
// nativemirror.EnsureBootstrapIntent + TrustReconciler.RunOnce. nil (the flag
// off, or dev/tests) means the admin enable-trust-root surface is not served.
type TrustEnabler interface {
	EnableTrustRoot(ctx context.Context, repoID model.RepoID) (TrustEnableResult, error)
}

// TrustEnableResult is the outcome of an enable-trust-root request.
type TrustEnableResult struct {
	// OperationID is the durable intent's operation id (idempotency key).
	OperationID string
	// Created is true when this call inserted a new intent, false on an
	// idempotent replay of an existing active or published one.
	Created bool
	// Provisioned is true when the reconciler is wired (fleet root profile +
	// seed present) and a publish was attempted; false when the intent was
	// recorded but the environment cannot publish yet.
	Provisioned bool
	// Drained is true when the reconcile pass claimed and progressed an intent.
	Drained bool
	// State is the intent's lifecycle state after the enable flow (a
	// nativemirror IntentState*): the creation state when unprovisioned, or the
	// post-drive outcome (published / failed / still pending) when provisioned.
	// Empty when it could not be read.
	State string
}

// ErrTrustNotOwningJurisdiction is returned by EnableTrustRoot when this core
// does not own the repo's primary placement jurisdiction. The owning core is the
// sole orchestration owner (ADR 20260724), so the caller must retarget it.
var ErrTrustNotOwningJurisdiction = errors.New("api: repo is not homed in this core's jurisdiction")

// TrustIntentReader reads a repo's trust-publication intents for the admin trust
// card's operational section: the control-plane record of each bootstrap or
// backfill attempt and its retry/pause status (state, attempts, next retry,
// pause reason). *nativemirror.Service implements it; nil omits the section.
// This is Core's own desired-state record, deliberately distinct from the signed
// data-plane state TrustReader returns, so the card can show a paused or
// retrying intent that has not yet reached rooted.
type TrustIntentReader interface {
	TrustIntentsForRepo(ctx context.Context, repoID model.RepoID) ([]nativemirror.TrustIntent, error)
	// PlacementAcceptancesForRepo reads Core's per-placement acceptance records
	// for the slice-4 placement matrix: which mirror placements have accepted a
	// published operation, which are behind, and which are quarantined.
	PlacementAcceptancesForRepo(ctx context.Context, repoID model.RepoID) ([]nativemirror.PlacementAcceptance, error)
}

// UnconfiguredBridge is the RepoBridge stand-in for every deployment
// where no live data-plane bridge is available: Config.RepoBridge nil
// (dev/tests), global mode (no cluster store), a jurisdiction with zero
// active clusters, or no internal mTLS client for cnf-bound tokens
// (dev). Provision/Delete return repoadmin.ErrNotConfigured
// wrapping Reason; handlers route that through their normal
// bridge-unavailable path (create keeps the row in provisioning for the
// reconciler; delete falls back to core-only cleanup). The reconciler
// recognises this type and idles rather than looping errors (COR-857).
type UnconfiguredBridge struct{ Reason string }

// NewUnconfiguredBridge builds the stand-in with a human reason for logs.
func NewUnconfiguredBridge(reason string) UnconfiguredBridge {
	return UnconfiguredBridge{Reason: reason}
}

func (b UnconfiguredBridge) Provision(context.Context, model.RepoID, string, string, string, int64, string, string, string, string, string) error {
	return fmt.Errorf("%w: %s", repoadmin.ErrNotConfigured, b.Reason)
}

func (b UnconfiguredBridge) GetTrustState(context.Context, model.RepoID, string) (repoadmin.TrustState, error) {
	return repoadmin.TrustState{}, fmt.Errorf("%w: %s", repoadmin.ErrNotConfigured, b.Reason)
}

func (b UnconfiguredBridge) Delete(context.Context, model.RepoID, string) error {
	return fmt.Errorf("%w: %s", repoadmin.ErrNotConfigured, b.Reason)
}

func (b UnconfiguredBridge) MarkMirrorInitialSyncDone(context.Context, model.RepoID, string) error {
	return fmt.Errorf("%w: %s", repoadmin.ErrNotConfigured, b.Reason)
}

func repoBridgeOrUnconfigured(b RepoBridge) RepoBridge {
	if b == nil {
		return NewUnconfiguredBridge("Config.RepoBridge was nil")
	}
	return b
}

// GitHubInstallationMinter is the contract the STS handler uses to mint
// GitHub App installation tokens. *githubapp.AppClient satisfies it for
// production; tests inject a fake.
//
// Exported so wireAPIServer can declare its local as the interface type
// and never carry a typed-nil concrete pointer into Config — assigning a
// nil concrete to an interface field produces a non-nil interface, which
// would silently defeat the handler's `s.ghAppCaps == nil` check.
type GitHubInstallationMinter interface {
	// InstallationToken mints (or serves from a Core-side cache) a
	// repository-scoped GitHub App installation token. fromCache reports
	// whether the token was served without a GitHub API call for this
	// request (a cache hit or a coalesced concurrent miss), so the handler's
	// audit log can distinguish a fresh mint from a reused token (COR-596).
	InstallationToken(ctx context.Context, installationID int64, repo string) (token string, expiresAt time.Time, fromCache bool, err error)
	// InstallationTokenForPush is the write-scoped counterpart used only for
	// an authorized entiredb mirror push-through request.
	InstallationTokenForPush(ctx context.Context, installationID int64, repo string) (token string, expiresAt time.Time, fromCache bool, err error)
	// InstallationTokenForChecks mints a repo-read + checks:read token, used by
	// entire-api's trail-gate checks evaluation to read GitHub check-runs. Kept
	// separate from InstallationToken so the checks scope is cache-isolated and
	// a plain-read caller can never receive it.
	InstallationTokenForChecks(ctx context.Context, installationID int64, repo string) (token string, expiresAt time.Time, fromCache bool, err error)
	// InstallationTokenForChecksWrite mints a repo-read + checks:write token,
	// used by entire-api to publish the trail-gates rollup as a check run.
	// Kept separate from InstallationTokenForChecks so a read caller can never
	// be widened into a writer.
	InstallationTokenForChecksWrite(ctx context.Context, installationID int64, repo string) (token string, expiresAt time.Time, fromCache bool, err error)
	// InstallationTokenForPullRequests mints a repo-read + pull_requests:write
	// token, used by entire-api to prepend the trail backlink to a PR body. It
	// grants no contents write.
	InstallationTokenForPullRequests(ctx context.Context, installationID int64, repo string) (token string, expiresAt time.Time, fromCache bool, err error)
}

// MirrorBootstrapper establishes the installation + github_repos rows
// for one (owner, repo) from the App's own credential. It writes no
// access edges — mirror authz lives in SpiceDB (COR-437); these rows
// only carry the installation_id the inbound-sync token mint and
// mirror-create lookups read.
//
// *permssnapshotter.Snapshotter satisfies this contract in production;
// tests inject a fake. Declared as an interface here for the same
// typed-nil safety reason as GitHubInstallationMinter — a nil concrete
// behind a non-nil interface would silently bypass the handler's
// "bootstrap not configured" 503 path.
type MirrorBootstrapper interface {
	// EnsureRepoKnown upserts the installation + github_repos rows from
	// the App's credential and returns the github_repo_id, the repo's
	// visibility, GitHub's canonical owner/repo casing, and its default
	// branch off the GitHub object it just persisted (so the create path can
	// seed SpiceDB visibility, the display full name, and the data-plane HEAD
	// without re-reading its own write). It does not gate on the caller's
	// access (that's authorizeUserMirrorCreate's job), only on the App being
	// installed upstream.
	EnsureRepoKnown(ctx context.Context, owner, repo string, observedAt time.Time) (githubRepoID int64, isPrivate bool, ownerLogin, repoName, defaultBranch string, err error)
	// RefreshRepoCollaborators re-snapshots the repo's collaborator read-model
	// from the live GitHub API and returns the github_repo_id. Used by resume to
	// reconcile against current GitHub truth.
	RefreshRepoCollaborators(ctx context.Context, owner, repo string, observedAt time.Time) (githubRepoID int64, err error)
}

// MirrorPermsBackfillPublisher enqueues an asynchronous job to reconcile all of
// a mirrored upstream's GitHub collaborators into SpiceDB, OFF the mirror-create
// request path. The creating user's own grant is written synchronously
// (grantMirrorCreator), so the backfill materialises everyone else; the periodic
// perms reconciler is the authoritative backstop if a job is lost. Optional — a
// nil publisher (e.g. dev without NATS) degrades to that reconciler.
type MirrorPermsBackfillPublisher interface {
	PublishBackfill(ctx context.Context, jurisdiction, clusterSlug string, githubRepoID int64) error
}

// MirrorSourceSizer reports an upstream repository's on-disk size at GitHub so
// mirror-create can reject a source that could never finish its initial sync
// push (see mirror_source_size.go). *githubgraphql.Client satisfies it; tests
// inject a fake. Optional — when the containing GitHubAppCapabilities leaves it
// nil, or any lookup fails, the create proceeds unguarded (fail open).
type MirrorSourceSizer interface {
	// RepoDiskUsageKiB returns GitHub's reported on-disk size of owner/repo in
	// kibibytes, using an installation access token. known is false when GitHub
	// reports no size (a null diskUsage, e.g. an empty repository).
	RepoDiskUsageKiB(ctx context.Context, token, owner, repo string) (kib int64, known bool, err error)
}

// Server is the HTTP API for entire-core. Its fields fall into three
// buckets — the census a new field should join deliberately, not get
// bolted onto loose (COR-832):
//
//  1. Core: dependencies and config knobs wired in every mode regardless
//     of jurisdiction or capability gating — mux, identity, authz,
//     resource, providers, githubPerms, githubUserAPI, mirrorRepos,
//     lifecycleEvents, the handle/platform-admin caches, oauthStateStore,
//     the jurisdiction*Hosts maps, rate limiters, and the string/bool
//     config fields (mode, jurisdiction, authBaseURL, and friends).
//
//  2. Four capability groups, each all-or-nothing (see the matching
//     New*Capabilities constructor: every field non-nil or a boot
//     error) and nil exactly when the owning mode does not wire it:
//     - routerCaps (RouterCapabilities) — global only.
//     - ghAppCaps (GitHubAppCapabilities) — any mode, gated on the
//     GitHub App being configured.
//     - jurCaps (JurisdictionCapabilities) — regional;
//     never global, which is the COR-730 incident-#1 guarantee
//     (RunReconciler hangs off this group, so global cannot
//     construct, let alone start, the reconciler).
//     - idpCaps (IdpCapabilities) — regional; never
//     global, which issues no sessions of its own.
//
//  3. Named top-level optionals that belong to no group, each with its
//     own independent gate:
//     - workos — nil disables the SSO endpoints (SSO-off-when-nil).
//     - githubTokens — nil until the token cipher is configured
//     (cipher-gated).
//     - cookie — nil until the home-jurisdiction cookie secret is
//     configured (secret-gated).
//     - jurisdictionVerifier, siblingAuthBaseURLs — cross-jurisdiction-
//     adjacent but each independently gated.
//     - clusterAdminTransport, internalTokenEndpoint,
//     internalTokenClient — the cluster-admin-proxy trio, gated
//     together on TLS config being present.
//     - analytics — nil-tolerant; every method on a nil client is a
//     no-op.
//     - erasureOutbox — nil-tolerant multi-region account-erasure
//     enqueuer; nil (e.g. account deletion not launched) skips the
//     fan-out enqueue rather than failing the delete.
//     - emailOutbox — nil-tolerant transactional-email enqueuer; nil
//     (e.g. email sending disabled) skips the enqueue rather than
//     failing the triggering operation.
//     - mirrorPermsBackfill — soft-degrade optional, deliberately
//     demoted out of JurisdictionCapabilities (see jurCaps below):
//     nil falls back to the periodic reconciler.
//     - regional, cluster, gitJobsPub — mirrored off jurCaps one-
//     for-one purely for read convenience at the many existing
//     direct call sites; always set together, nil together, never
//     independently gated.
type Server struct {
	mux         *http.ServeMux
	identity    identity.Service
	handleCache *HandleStateCache
	// platformAdminCache memoizes platform-admin checks for the admin SPA
	// bundle gate only (ENT-755). Not used by the admin API handlers,
	// which stay live/uncached.
	platformAdminCache *platformAdminCache
	// jurisdictionVerifier accepts the jurisdiction token on the /api/v1
	// resource surface only — see AuthMiddleware. nil disables
	// jurisdiction-token acceptance (single-host dev).
	jurisdictionVerifier *jwtverify.Verifier
	// jurisdictionAudience is the exact audience jurisdictionVerifier pins;
	// IsJurisdictionToken classifies against it. Empty when
	// jurisdictionVerifier is nil.
	jurisdictionAudience string
	// siblingSubjectVerifiers verifies github-access-token exchange
	// subjects a sibling core minted, keyed by the sibling's iss (its
	// AuthBaseURL). Built from SiblingAuthBaseURLs — the same trust set
	// the oidcop dispatcher uses for cross-juris subject_token validation.
	// It admits the legacy repo-scoped push credential (COR-941) and the
	// sibling's self-audienced account access token (COR-1111); the handler
	// classifies the verified shape. nil when no siblings are configured
	// (single-region).
	siblingSubjectVerifiers *jwtverify.TrustedIssuers
	authz                   authz.Service
	regional                regional.Service
	resource                resource.Service
	automation              automation.Service
	erasureOutbox           ErasureEnqueuer
	erasureLedger           *erasureledger.Store
	emailOutbox             EmailEnqueuer
	// ceoWelcomeEnabled mirrors Config.CEOWelcomeEnabled — see there.
	ceoWelcomeEnabled bool
	cluster           *cluster.Store
	providers         *authn.ProviderRegistry
	githubTokens      *githubtokens.Service
	githubPerms       *githubperms.Service
	// oidcFed + domainAudit were formerly bundled in idpCaps; lifted to
	// top-level so non-auth-host cores (global) and the account-deletion reaper
	// can wire them without the full auth-login stack. See ADR 20260707.
	oidcFed       oidcfed.Service
	domainAudit   *audit.DomainAudit
	githubUserAPI GitHubUserInstallationsAPI
	userPermsSync UserPermsSyncer
	// availableMirrorsReadModel, when true, serves GET /api/v1/mirrors/available
	// from the local github_user_repo_access read-model once the selected gate
	// clears. Off keeps the original live-GitHub path. NOT an authz toggle.
	availableMirrorsReadModel bool
	availableMirrorsUserFresh bool
	permsUserSyncTTL          time.Duration
	// availableMirrorsPerms is githubPerms behind the readiness-gate TTL cache
	// (see mirrors_available_readiness_cache.go); the /mirrors/available serve
	// path reads through this, everything else keeps the uncached service.
	// nil iff githubPerms is nil.
	availableMirrorsPerms availableMirrorsReadModelSource
	// githubTokenIdentityExchange gates the jurisdiction-token subject shape on
	// the STS github-access-token exchange (COR-813). Off = repo-push only.
	githubTokenIdentityExchange bool
	mirrorRepos                 *mirrorrepo.Service
	mirrorRequests              *mirrorrequest.Store
	mirrorRequestPublisher      mirrorrequest.Publisher
	nativeMirrors               *nativemirror.Service
	nativeMirrorEnabled         bool
	nativeMirrorCreateEnabled   bool
	gitJobsPub                  *gitjobs.Publisher
	// resyncPub publishes a synthetic GitHub push webhook to the central
	// webhooks_github_v1 stream to trigger a mirror-pipeline resync (ENT-1172).
	// Optional — nil (e.g. no NATS configured) makes ResyncMirror return
	// ErrResyncUnavailable, which handlers map to 503. See ResyncPublisher.
	resyncPub       ResyncPublisher
	lifecycleEvents *resourceevents.Emitter
	analytics       *analytics.Client
	// ghAppCaps is everything minted from the configured GitHub App key
	// (STS minter, admin checker, mirror bootstrapper). nil when
	// ENTIRE_GITHUB_APP_ID is unset — see GitHubAppCapabilities.
	ghAppCaps           *GitHubAppCapabilities
	mirrorPermsBackfill MirrorPermsBackfillPublisher
	// workos is optional — nil disables the SSO endpoints. Enable by
	// providing a configured *workos.Service.
	workos                 *workos.Service
	githubClientID         string
	githubClientSecret     string
	githubRedirectURL      string            // OAuth callback URL registered with GitHub
	githubAppPublicURL     string            // public "install the App" URL surfaced to users (empty → prod default)
	authBaseURL            string            // IdP/auth origin (issuer, audience, /api/auth/*, /cli/auth)
	consoleURL             string            // user-facing console UI origin (post-login, /logged-out)
	ciWebhooksURL          string            // entire-ci-webhooks leaf public URL (ops-token audience + dial base); empty where unreachable
	ciWebhooksURLs         map[string]string // cluster slug -> that cell's ci-webhooks URL; empty means every placement uses ciWebhooksURL
	firstPartyOrigins      []string          // extra first-party SPA origins for /oauth/token allowlist (COR-361)
	primaryLoginURL        string            // front-door login URL (e.g. https://partial.to/login); empty in single-host dev
	mode                   string            // "global", "regional" (or "reaper" / "" in internal wiring and tests)
	jurisdiction           string            // "us", "eu" (regional only)
	deployEnv              string            // staging or production (empty in local dev)
	accountDeletionEnabled bool              // launch gate for self-service account deletion

	cookie            *authn.HomeJurisdictionCookie
	oauthStateStore   *authn.OAuthStateStore
	jurisdictionHosts map[string]string
	// jurisdictionAuthHosts maps each jurisdiction to its OIDC issuer URL.
	// Read by every cross-jurisdiction redirect whose target is on the
	// auth host. Populated by entirecore.MergeAuthHosts, which per-key
	// falls back to jurisdictionHosts; the fallback is safe while auth
	// and console DNS terminate on the same backend.
	// TODO(COR-256): drop the fallback in entirecore once every overlay
	// sets JURISDICTION_AUTH_HOSTS.
	jurisdictionAuthHosts map[string]string
	// jurisdictionAPIHosts maps each jurisdiction to its entire-api base URL
	// (the cell-bound data API). Surfaced per-jurisdiction on GET
	// /api/v1/clusters (Cluster.apiUrl). Plain addressing — no auth/trust
	// role and no console-host fallback — so an unset jurisdiction simply
	// reports an empty apiUrl.
	jurisdictionAPIHosts map[string]string
	// entireAPIInternalURL is THIS cell's entire-api internal mTLS listener base
	// URL, dialled by the cell-state admin proxy (handleAdminRepoCellState).
	entireAPIInternalURL string
	// siblingAuthBaseURLs is the federated peer list emitted on
	// /.well-known/entire-federation. Populated only from the raw
	// JURISDICTION_AUTH_HOSTS map (never the console-host fallback),
	// minus the local AuthBaseURL — so the CLI sees the same trust set
	// the oidcop dispatcher uses for cross-juris subject_token
	// validation. Empty / nil in modes where cross-juris isn't wired.
	siblingAuthBaseURLs []string

	// routerCaps is the global-mode front-door surface (the home-jurisdiction
	// router). nil on regional servers — see RouterCapabilities.
	routerCaps *RouterCapabilities

	// jurCaps is the jurisdiction-bound data-plane surface (regional store,
	// cluster fixture, entiredb bridge, git-jobs publisher, plus a duplicate
	// resource reference) that regional wires as a unit and global
	// cannot construct at all — see JurisdictionCapabilities. nil on global
	// servers. The provisioning-reconciler subsystem (COR-832) is built from
	// this value, never from the Server directly, which is what makes a
	// global server structurally unable to start it (the COR-730 incident-#1
	// guarantee).
	//
	// regional, cluster, and gitJobsPub below mirror jurCaps's fields
	// one-for-one (set together at construction, nil together) so the many
	// existing call sites that read them directly are untouched by this
	// group's introduction; only the handler-boundary nil-checks that used to
	// gate on those fields individually now gate on jurCaps.
	jurCaps *JurisdictionCapabilities

	// waitlistMode gates new-account approval at creation across any
	// self-service signup path the global server owns (none today — account
	// creation is regional). Mirrors loginflow.Flow.waitlistMode: when true, fresh accounts
	// are created unapproved (approved=false) and stay waitlisted until an admin
	// approves them. See ADR 20260618-waitlist-approval-gate.
	waitlistMode bool

	// idpCaps is the identity-provider surface (login flow, JWT issuer, key
	// store, verifier, pkg/op provider, every session store/cookie pair,
	// auth-request bridge, client registry, device-grant store, system
	// login, service account, oidcfed, token-endpoint client, domain audit)
	// that regional wires as a unit and global cannot construct at
	// all — see IdpCapabilities. nil on global servers.
	idpCaps *IdpCapabilities

	// frontendFS powers the device-flow browser approval page. Nil-tolerant:
	// the device flow returns 503 server_error when missing, so a
	// deployment that hasn't wired it up doesn't break unrelated routes.
	frontendFS fs.FS

	// tokenEndpointURL is the IdP's /api/auth/token URL as seen from the RP
	// side. In single-binary deployments the IdP and RP are the same
	// process, but the call still goes over HTTP so the trust boundary is
	// enforced by client_id/secret, not by DB sharing. The client built
	// from it lives on idpCaps.TokenEndpointClient.
	tokenEndpointURL string

	// repoBridge is the entiredb RepoAdmin client used by handleCreateRepo,
	// handleAdminDeleteRepo, and the provisioning reconciler. Declared as
	// an interface so tests can inject fakes.
	repoBridge RepoBridge

	// trustReader reads read-only trust state for the admin trust card; nil
	// (no data-plane bridge) renders every read as "status unavailable".
	// clusterFixtureEnv selects the fixture the fleet root profile is read
	// from for that card.
	trustReader       TrustReader
	trustEnabler      TrustEnabler
	trustIntents      TrustIntentReader
	clusterFixtureEnv string

	// allowedClusterDomain is the suffix every `cluster` and `return_to`
	// host must match for /api/authz/debug-bounce (e.g. "partial.to").
	// Empty disables the bounce endpoint.
	allowedClusterDomain string

	// handoffReturnToHosts is the exact-host allowlist for `return_to` on
	// GET /api/auth/resolve-jurisdiction (e.g. the entire.io BFF's callback
	// host). Empty disables the endpoint.
	handoffReturnToHosts []string

	// loginStartURL is the BFF's jurisdictional login-start URL. The global
	// router bounces here when it can't complete a handback (invalid/expired
	// state), and its origin is the bare-root redirect target. Empty disables
	// both (callers degrade to the auth error page / landing).
	loginStartURL string

	// clusterAdminTransport is the mTLS transport the cluster-admin
	// proxy dials entiredb with. Nil leaves the proxy disabled.
	clusterAdminTransport *http.Transport

	// internalTokenEndpoint and internalTokenClient drive the cluster-
	// admin proxy's on-behalf-of token mint: a loopback mTLS POST to
	// this core's own /oauth/token so the issued JWT's cnf binds to
	// entire-core's client leaf at mint time (COR-337). Mirrors the
	// repoadmin BearerTransport wiring; empty/nil falls the proxy back
	// to the in-process IssueOpsToken signer.
	internalTokenEndpoint string
	internalTokenClient   *http.Client

	// ipRateLimit enforces tiered per-IP limits (global + stricter auth +
	// tightest system-login) over the whole public chain; userRateLimit
	// enforces per-principal limits on the authenticated /api/v1 and
	// /api/admin surface. Both are no-ops in test mode. See ratelimit.go.
	ipRateLimit   *ratelimit.HTTPLimiter
	userRateLimit *ratelimit.Limiter
	// stsRateLimit throttles /api/authz/sts/token per verified subject account
	// inside handleGitHubAccessTokenExchange (COR-937): on the dominant
	// BFF-mediated path core sees only the shared Cloudflare egress IP so IP
	// keying can't separate users, and per-verified-subject keying is the right
	// identity for that path and the non-BFF mirror-push flow alike. No-op in
	// test mode. See ratelimit.go.
	stsRateLimit *ratelimit.Limiter

	oauthMu     sync.Mutex
	oauthStates map[string]oauthState // CSRF state → metadata
}

type oauthState struct {
	expiry        time.Time
	payload       string
	provider      string
	authRequestID string
}

const oauthStateTTL = 10 * time.Minute

func defaultConsoleClientID(clientID string) string {
	if clientID == "" {
		return "console"
	}
	return clientID
}

type Config struct {
	Identity identity.Service
	// JurisdictionVerifier accepts the jurisdiction token on the /api/v1
	// resource surface. nil disables jurisdiction-token acceptance.
	JurisdictionVerifier *jwtverify.Verifier
	// JurisdictionAudience is the exact audience JurisdictionVerifier pins
	// (the same value it was constructed with via jwtverify.
	// NewIdentityVerifier) — callers that need to read the pinned audience
	// back (IsJurisdictionToken, cell-state token minting) use this rather
	// than reaching into the verifier, which doesn't expose it. Empty when
	// JurisdictionVerifier is nil.
	JurisdictionAudience string
	Authz                authz.Service
	Resource             resource.Service
	// Automation manages the automations table (provenance for automation
	// principals, ADR 20260728-automation-principal). Nil disables the
	// repo-delete automation sweep (finalizeRepoDeleteCore treats it the
	// same as "nothing declared" — a no-op — matching the nativeMirrors nil
	// case just above it).
	Automation automation.Service
	// ErasureOutbox durably records multi-region account-erasure events at
	// teardown; a relay fans them to every region. Nil disables the fan-out
	// (tests) — the home region still erases synchronously.
	ErasureOutbox ErasureEnqueuer
	// ErasureLedger records the cross-target erasure ledger (requests + tasks)
	// for GDPR demonstrability (ADR 20260702). Nil disables ledger recording
	// (tests without it wired); the actual erasure is unaffected —
	// all ledger writes are best-effort.
	ErasureLedger *erasureledger.Store
	// EmailOutbox durably records transactional-email events (e.g. waitlist
	// confirmation); a relay publishes them. Nil disables enqueuing (no NATS
	// configured — dev/CI).
	EmailOutbox EmailEnqueuer
	// CEOWelcomeEnabled selects which Kind handleApproveUser enqueues on a
	// genuine waitlist->approved transition: false (default) enqueues
	// KindWaitlistAccepted; true switches to KindCEOWelcome
	// (ENTIRE_CEO_WELCOME_ENABLED). Lets the "CEO welcome" send-path deploy
	// dark and be verified/enabled independently of the code rollout.
	CEOWelcomeEnabled bool
	Providers         *authn.ProviderRegistry
	GitHubTokens      *githubtokens.Service
	// OIDCFed + DomainAudit are account-scoped teardown deps (federation-binding
	// erase + the deletion audit trail). Formerly inside IdpCaps; lifted to
	// top-level (ADR 20260707) so global-mode and the reaper get them without the
	// auth-login stack. Set in every mode by buildAPIConfig. Nil-tolerant.
	OIDCFed     oidcfed.Service
	DomainAudit *audit.DomainAudit
	// GitHubPerms is the read/write client for the global GitHub
	// permission mirror. Required for mirror create/delete
	// (CreateMirrorPlacement / DeleteMirrorPlacement); nil in legacy
	// fixtures that pre-date the perms layer.
	GitHubPerms *githubperms.Service
	// GitHubUserAPI lists the installations + repos the caller can reach with
	// their own user-to-server token, backing the available-mirror listing
	// (ListAvailableMirrors). nil disables that endpoint (503).
	GitHubUserAPI GitHubUserInstallationsAPI
	// UserPermsSync triggers the COR-986 user-centric perms sync; nil (the
	// flag-off state) disables every trigger.
	UserPermsSync UserPermsSyncer
	// AvailableMirrorsReadModel serves /mirrors/available from the local
	// github_user_repo_access read-model instead of calling GitHub live
	// (ENTIRE_GITHUB_PERMS_READ_MODEL_ENABLED). Falls back to the live path
	// until its configured completeness gate clears. NOT an authz toggle
	// (COR-435).
	AvailableMirrorsReadModel bool
	// AvailableMirrorsUserFreshness gates the read-model on the caller's
	// complete user-sync freshness instead of collaborator snapshots. Read
	// only when AvailableMirrorsReadModel is also set.
	AvailableMirrorsUserFreshness bool
	// PermsUserSyncTTL is the freshness window shared by user permission sync
	// and repository discovery. Unset, nothing is ever fresh enough for
	// AvailableMirrorsUserFreshness to serve locally.
	PermsUserSyncTTL time.Duration
	// GitHubTokenIdentityExchange admits the caller's own jurisdiction token as
	// the subject of the STS github-access-token exchange (self-scoped), letting
	// the BFF source a user's GitHub token from core (COR-813). Off leaves the
	// exchange accepting only a repo-scoped push token, exactly as before
	// (ENTIRE_GITHUB_TOKEN_IDENTITY_EXCHANGE_ENABLED).
	GitHubTokenIdentityExchange bool
	// MirrorRepos owns the mirror_repos + github_mirror_repo_urls
	// tables. Required for mirror create/delete.
	MirrorRepos *mirrorrepo.Service
	// MirrorRequests stores asynchronous mirror-placement requests.
	MirrorRequests         *mirrorrequest.Store
	MirrorRequestPublisher mirrorrequest.Publisher
	// NativeMirrors owns the global native_mirrors lifecycle-intent table.
	// NativeMirrorEnabled mounts status/delete/create routes and the serve-layer
	// reconciler. NativeMirrorCreateEnabled independently admits POST so a
	// rollback can stop new work without stranding accepted intents.
	NativeMirrors             *nativemirror.Service
	NativeMirrorEnabled       bool
	NativeMirrorCreateEnabled bool
	// MirrorPermsBackfill enqueues the async collaborator-reconcile job on
	// mirror create so the request returns without blocking on a per-collaborator
	// SpiceDB reconcile. Optional — nil (e.g. dev without NATS) falls back to the
	// periodic reconciler; a publish failure never fails the create.
	MirrorPermsBackfill MirrorPermsBackfillPublisher
	// LifecycleEvents publishes resource create/delete notifications onto
	// NATS (COR-616). Optional and best-effort — nil disables emission
	// (local dev without NATS); a publish failure never fails the request.
	LifecycleEvents *resourceevents.Emitter
	// ResyncPub publishes the synthetic push webhook that triggers a
	// mirror-pipeline resync (ENT-1172). Optional — nil (no NATS) makes
	// ResyncMirror return ErrResyncUnavailable. See ResyncPublisher.
	ResyncPub ResyncPublisher
	// Analytics is the shared PostHog client; the coreapi handler uses it to
	// emit the api_request product-analytics event. Optional and best-effort —
	// a nil or disabled client makes capture a no-op.
	Analytics *analytics.Client
	// GitHubAppCaps is everything minted from the configured GitHub App key
	// (STS minter, admin checker, mirror bootstrapper). Present iff
	// ENTIRE_GITHUB_APP_ID is configured; nil makes the STS mint, mirror
	// admin gate, and bootstrap paths 503. See GitHubAppCapabilities.
	GitHubAppCaps *GitHubAppCapabilities
	// WorkOS is optional — nil disables the SSO endpoints. Enable by
	// providing a configured *workos.Service.
	WorkOS             *workos.Service
	GitHubClientID     string
	GitHubClientSecret string
	GitHubRedirectURL  string
	// GitHubAppPublicURL is the public URL where users install the GitHub
	// App, surfaced verbatim in the mirror-create "app not installed"
	// error. Empty falls back to the prod App (defaultGitHubAppPublicURL);
	// staging overrides it via GITHUB_APP_PUBLIC_URL.
	GitHubAppPublicURL string
	// AuthBaseURL is the IdP/auth origin: JWT issuer + audience claim,
	// /api/auth/{login,authorize,callback,token}, /cli/auth. Required.
	AuthBaseURL string
	// ConsoleURL is the user-facing console UI origin (post-login,
	// /logged-out, any browser-target URL meant for the console).
	// Required.
	ConsoleURL string
	// CIWebhooksURL is the entire-ci-webhooks leaf's public URL: the base the
	// core→leaf client dials and the origin the repo#manage_ci ops-token
	// audience (<url>/admin) is derived from. Empty where CI-webhooks isn't
	// reachable (v1 is US-only), which makes the user-facing enroll 503.
	CIWebhooksURL string
	// CIWebhooksURLs maps an entiredb cluster slug to that cell's ci-webhooks URL.
	// Empty means every placement uses CIWebhooksURL. See CIWebhooksBaseURLFor.
	CIWebhooksURLs map[string]string
	// FirstPartyOrigins are extra first-party SPA origins admitted to
	// the cookie-driven /oauth/token Origin allowlist, beyond
	// AuthBaseURL + ConsoleURL (COR-361). Empty for most deployments.
	FirstPartyOrigins []string
	// PrimaryLoginURL is the front-door login URL (typically
	// https://partial.to/auth/start or its staging equivalent).
	// When set in a split deployment, /api/auth/login hits that
	// arrive on the auth host bounce here instead of trying to
	// start a console login flow on the wrong origin. Empty
	// disables the bounce — fine for single-host dev where auth and
	// console share a host.
	PrimaryLoginURL   string
	Mode              string
	Jurisdiction      string
	Cookie            *authn.HomeJurisdictionCookie
	OAuthStateStore   *authn.OAuthStateStore
	JurisdictionHosts map[string]string
	// JurisdictionAuthHosts maps each jurisdiction to its OIDC issuer URL.
	// Read by cross-jurisdiction redirects targeting auth-host endpoints.
	// Wiring is in entirecore.MergeAuthHosts; tests construct it directly
	// only when they exercise a cross-jurisdiction code path.
	JurisdictionAuthHosts map[string]string
	// JurisdictionAPIHosts maps each jurisdiction to its entire-api base URL
	// (the cell-bound data API). Surfaced per-jurisdiction on GET
	// /api/v1/clusters (Cluster.apiUrl); plain addressing, no fallback.
	JurisdictionAPIHosts map[string]string
	// EntireAPIInternalURL is THIS cell's entire-api internal mTLS listener base
	// URL, dialled by the cell-state admin proxy.
	EntireAPIInternalURL string
	// SiblingAuthBaseURLs is the federated peer set emitted on
	// /.well-known/entire-federation. Must contain only AuthBaseURLs
	// from the raw JURISDICTION_AUTH_HOSTS (never console-host
	// fallbacks) and must not contain the local AuthBaseURL. Empty in
	// modes that don't run cross-juris session exchange.
	SiblingAuthBaseURLs []string
	// RouterCaps is the global-mode front-door surface (the home-jurisdiction
	// router). Required in global mode; nil on regional. See RouterCapabilities.
	RouterCaps *RouterCapabilities
	// JurisdictionCaps is the jurisdiction-bound data-plane surface
	// (regional store, cluster fixture, entiredb bridge, git-jobs publisher)
	// regional wires as a unit. Required there; a global
	// server cannot construct it at all (no regional store) — see
	// JurisdictionCapabilities.
	JurisdictionCaps *JurisdictionCapabilities
	// WaitlistMode gates new-account approval for any self-service signup
	// paths this server owns (none today). When true, those accounts
	// are created unapproved. Must match the LoginFlow's WaitlistMode — both
	// are wired from ENTIRE_WAITLIST_MODE. See ADR 20260618-waitlist-approval-gate.
	WaitlistMode bool

	// IdpCaps is the identity-provider surface (login flow, JWT issuer, key
	// store, verifier, pkg/op provider, every session store/cookie pair,
	// auth-request bridge, client registry, device-grant store, system
	// login, service account, oidcfed, token-endpoint client, domain audit)
	// regional wires as a unit. Required there; a global
	// server cannot construct it at all — see IdpCapabilities.
	IdpCaps *IdpCapabilities

	// FrontendFS exposes the Vite-built SPA used by the device-flow
	// approval page (and any future user-facing entire-core pages). Pass
	// frontend.FS() from the cmd/entire-core wiring. Optional — without it
	// /cli/auth returns 503.
	FrontendFS fs.FS

	// TokenEndpointURL is the IdP's /api/auth/token URL as seen from the RP
	// side. In-process it is typically the server's own baseURL; in a split
	// deployment it is the IdP origin. Also fed into IdpCapabilities'
	// TokenEndpointClient construction — see NewIdpCapabilities.
	TokenEndpointURL string

	// ConsoleClientSecret is the RP credential this server presents when
	// calling the IdP's /api/auth/token to finalise a console session. Fed
	// into NewIdpCapabilities alongside TokenEndpointURL; the matching
	// client_id lives on IdpCapabilities.ConsoleClientID.
	ConsoleClientSecret string

	// RepoBridge is the entiredb RepoAdmin client. If nil, handleCreateRepo
	// responds 202 (provisioning) on every attempt so the reconciler closes
	// the loop when a client is eventually configured; admin delete-repo
	// proceeds with core-side cleanup and logs the skipped data-plane call.
	RepoBridge RepoBridge

	// TrustEnabler serves the admin enable-trust-root surface; nil leaves it
	// unregistered (the flag off, or dev/tests).
	TrustEnabler TrustEnabler

	// TrustReader reads read-only RSL trust state from the data plane for the
	// admin trust card (GET /api/admin/repos/{id}/trust). nil disables the
	// read, so the card reports "status unavailable". The production wiring
	// passes the same *repoadmin.Router used for RepoBridge.
	TrustReader TrustReader

	// TrustIntentReader reads a repo's trust-publication intents for the admin
	// trust card's operational section. The production wiring passes the same
	// *nativemirror.Service used for NativeMirrors; nil omits the section.
	TrustIntentReader TrustIntentReader

	// ClusterFixtureEnv selects the embedded cluster fixture the trust card
	// reads the fleet root profile from (staging, prod, or local). Empty
	// leaves the target-root-profile and preflight view unavailable.
	ClusterFixtureEnv string

	// AllowedClusterDomain enables /api/authz/debug-bounce when set:
	// `cluster` and `return_to` host params must equal or be a subdomain
	// of this suffix (e.g. "partial.to"). Empty disables the endpoint.
	AllowedClusterDomain string

	// JurisdictionHandoffReturnToHosts enables GET
	// /api/auth/resolve-jurisdiction when set: `return_to` must exactly
	// match one of these hosts (e.g. "auth.partial.to"). Empty disables the
	// endpoint.
	JurisdictionHandoffReturnToHosts []string

	// LoginStartURL is the BFF's jurisdictional login-start URL. The global
	// router bounces here when it can't complete a handback (invalid/expired
	// state), and its origin is the bare-root redirect target. Empty disables
	// both (callers degrade to the auth error page / landing).
	LoginStartURL string

	// ClusterAdminTransport is the mTLS *http.Transport used by the
	// cluster-admin proxy (handlers in cluster_handlers.go) to dial
	// entiredb's :8281 svctok listener at cluster.InternalURL. Same
	// transport as the repoadmin bridge — one PCA-issued cert per pod,
	// used both as server (entire-core's own :8281 mTLS server) and
	// client. Nil disables the cluster-admin proxy: handlers respond
	// with 503 so deploys that haven't wired the bundle don't 500.
	ClusterAdminTransport *http.Transport

	// InternalTokenEndpoint is the OAuth issuer base URL (no
	// /oauth/token suffix) the cluster-admin proxy POSTs to for an
	// on-behalf-of ops-access JWT. InternalTokenClient is the mTLS
	// loopback client that dials it (ServerName pinned to a DNS SAN on
	// the client cert, so the listener handler stamps cnf from the
	// presented leaf). Both empty/nil falls the proxy back to the
	// in-process IssueOpsToken signer — the same dev
	// degradation the repoadmin bridge takes.
	InternalTokenEndpoint string
	InternalTokenClient   *http.Client

	// TestMode disables rate limiting (per-IP and per-principal). Tests
	// drive many requests from one loopback IP and reuse a single
	// principal, which the real limits would turn into flaky 429s.
	// Production wiring (entirecore) leaves this false.
	TestMode bool

	// DeployEnv labels the deployment (ENTIRE_DEPLOY_ENV: staging or
	// production in fleet; empty in local dev). Surfaced on /api/info as
	// environment so the admin console can show which world this is.
	DeployEnv string

	// AccountDeletionEnabled is the launch gate for self-service account
	// deletion (ENTIRE_ACCOUNT_DELETION_ENABLED, default false). When off,
	// DELETE /me + /me/cancel-deletion + /me/deletion-preview are not registered
	// (404) — so the feature ships dark and can't be triggered even by direct
	// API call until flipped on in lockstep with the frontend flag. The reaper
	// honors the same flag (no-op when off), so the already-scheduled CronJob
	// stays inert until launch.
	AccountDeletionEnabled bool
}

func NewServer(cfg Config) *Server {
	s := &Server{
		mux:                         http.NewServeMux(),
		identity:                    cfg.Identity,
		handleCache:                 NewHandleStateCache(stateCheckTTL, cfg.Identity),
		jurisdictionVerifier:        cfg.JurisdictionVerifier,
		jurisdictionAudience:        cfg.JurisdictionAudience,
		authz:                       cfg.Authz,
		resource:                    cfg.Resource,
		automation:                  cfg.Automation,
		erasureOutbox:               cfg.ErasureOutbox,
		erasureLedger:               cfg.ErasureLedger,
		emailOutbox:                 cfg.EmailOutbox,
		ceoWelcomeEnabled:           cfg.CEOWelcomeEnabled,
		providers:                   cfg.Providers,
		githubTokens:                cfg.GitHubTokens,
		githubPerms:                 cfg.GitHubPerms,
		oidcFed:                     cfg.OIDCFed,
		domainAudit:                 cfg.DomainAudit,
		githubUserAPI:               cfg.GitHubUserAPI,
		userPermsSync:               cfg.UserPermsSync,
		availableMirrorsReadModel:   cfg.AvailableMirrorsReadModel,
		availableMirrorsUserFresh:   cfg.AvailableMirrorsUserFreshness,
		permsUserSyncTTL:            cfg.PermsUserSyncTTL,
		githubTokenIdentityExchange: cfg.GitHubTokenIdentityExchange,
		mirrorRepos:                 cfg.MirrorRepos,
		mirrorRequests:              cfg.MirrorRequests,
		mirrorRequestPublisher:      cfg.MirrorRequestPublisher,
		nativeMirrors:               cfg.NativeMirrors,
		nativeMirrorEnabled:         cfg.NativeMirrorEnabled,
		nativeMirrorCreateEnabled:   cfg.NativeMirrorCreateEnabled,
		mirrorPermsBackfill:         cfg.MirrorPermsBackfill,
		resyncPub:                   cfg.ResyncPub,
		lifecycleEvents:             cfg.LifecycleEvents,
		analytics:                   cfg.Analytics,
		ghAppCaps:                   cfg.GitHubAppCaps,
		workos:                      cfg.WorkOS,
		githubClientID:              cfg.GitHubClientID,
		githubClientSecret:          cfg.GitHubClientSecret,
		githubRedirectURL:           cfg.GitHubRedirectURL,
		githubAppPublicURL:          strings.TrimRight(cfg.GitHubAppPublicURL, "/"),
		authBaseURL:                 cfg.AuthBaseURL,
		consoleURL:                  cfg.ConsoleURL,
		ciWebhooksURL:               strings.TrimRight(cfg.CIWebhooksURL, "/"),
		ciWebhooksURLs:              normalizeCIWebhooksURLs(cfg.CIWebhooksURLs),
		firstPartyOrigins:           cfg.FirstPartyOrigins,
		primaryLoginURL:             strings.TrimRight(cfg.PrimaryLoginURL, "/"),
		mode:                        cfg.Mode,
		jurisdiction:                cfg.Jurisdiction,
		deployEnv:                   cfg.DeployEnv,
		accountDeletionEnabled:      cfg.AccountDeletionEnabled,
		cookie:                      cfg.Cookie,
		oauthStateStore:             cfg.OAuthStateStore,
		jurisdictionHosts:           cfg.JurisdictionHosts,
		jurisdictionAuthHosts:       cfg.JurisdictionAuthHosts,
		jurisdictionAPIHosts:        cfg.JurisdictionAPIHosts,
		entireAPIInternalURL:        cfg.EntireAPIInternalURL,
		siblingAuthBaseURLs:         cfg.SiblingAuthBaseURLs,
		routerCaps:                  cfg.RouterCaps,
		jurCaps:                     cfg.JurisdictionCaps,
		waitlistMode:                cfg.WaitlistMode,
		idpCaps:                     cfg.IdpCaps,
		frontendFS:                  cfg.FrontendFS,
		tokenEndpointURL:            cfg.TokenEndpointURL,
		repoBridge:                  repoBridgeOrUnconfigured(cfg.RepoBridge),
		trustReader:                 cfg.TrustReader,
		trustEnabler:                cfg.TrustEnabler,
		trustIntents:                cfg.TrustIntentReader,
		clusterFixtureEnv:           cfg.ClusterFixtureEnv,
		allowedClusterDomain:        cfg.AllowedClusterDomain,
		handoffReturnToHosts:        cfg.JurisdictionHandoffReturnToHosts,
		loginStartURL:               cfg.LoginStartURL,
		clusterAdminTransport:       cfg.ClusterAdminTransport,
		internalTokenEndpoint:       cfg.InternalTokenEndpoint,
		internalTokenClient:         cfg.InternalTokenClient,
		oauthStates:                 make(map[string]oauthState),
	}
	var siblingIssuers []string
	for _, u := range cfg.SiblingAuthBaseURLs {
		if u == "" || u == s.authBaseURL {
			continue
		}
		siblingIssuers = append(siblingIssuers, u)
	}
	if len(siblingIssuers) > 0 {
		// No audience pinned: repo-push audiences vary per repo and cluster,
		// while account access tokens name the sibling's own AuthBaseURL.
		// The github-access-token handler classifies the verified shape.
		s.siblingSubjectVerifiers = jwtverify.NewTrustedIssuers(siblingIssuers, siblingJWKSCacheTTL,
			jwtverify.WithObserver(authn.RecordTokenVerifiedObserver("sibling")),
			jwtverify.WithFetchObserver(authn.RecordJWKSFetchObserver("sibling")),
			jwtverify.WithHTTPClient(authn.JWKSHTTPClient()))
	}
	if cfg.GitHubPerms != nil {
		s.availableMirrorsPerms = newReadinessCachingPermsSource(cfg.GitHubPerms)
	}
	// regional, cluster, and gitJobsPub mirror jurCaps's fields one-for-one
	// (see the jurCaps field doc comment): populated together here, nil
	// together on a global server, so the many existing call sites reading
	// them directly need no change — only the handler-boundary gates that
	// used to check these fields individually now check jurCaps as a group.
	if cfg.JurisdictionCaps != nil {
		s.regional = cfg.JurisdictionCaps.Regional
		s.cluster = cfg.JurisdictionCaps.Cluster
		s.gitJobsPub = cfg.JurisdictionCaps.GitJobsPub
	}
	s.platformAdminCache = newPlatformAdminCache(s.checkPlatformAdmin)
	// Hand the cache's invalidator to the identity Store so
	// DeleteAccount / CreateAccountWithHandle drop the LRU entry instead
	// of waiting out the 5s TTL. Only the concrete *identity.Store
	// supports this — interface-only fakes used in some tests don't,
	// and skipping silently is fine: those tests don't exercise resignup
	// timing.
	if store, ok := cfg.Identity.(*identity.Store); ok {
		store.SetHandleCacheInvalidator(s.handleCache)
	}
	s.ipRateLimit, s.userRateLimit, s.stsRateLimit = newRateLimiters(cfg.TestMode)
	s.routes()
	return s
}

// RunRateLimitCleanup runs the rate-limiter eviction loop, blocking until ctx
// is cancelled, then returns nil. This is the blocking form the serve-layer
// subsystem runner drives (COR-832); the loop itself lives in
// ratelimit.StartCleanup, which spawns the ticker goroutine and stops it on
// ctx.Done. Returning nil only after ctx cancellation means the runner treats
// the exit as a clean shutdown rather than a premature exit.
//
//nolint:unparam // error result is dictated by the subsystem.run func(ctx) error contract; cleanup never fails.
func (s *Server) RunRateLimitCleanup(ctx context.Context) error {
	ratelimit.StartCleanup(ctx, s.ipRateLimit, s.userRateLimit, s.stsRateLimit)
	<-ctx.Done()
	return nil
}

// STSTokenHandler returns the bare /api/authz/sts/token handler so an
// alternate listener (e.g. entire-core's internal mTLS listener for
// service-to-service callers) can mount it without going through the
// public mux. Most exchanges use the form's subject_token as the
// credential; internal-only exchanges may instead rely on transport-level
// identity (mTLS peer cert workload) that the alternate listener gates
// before this handler runs.
func (s *Server) STSTokenHandler() http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		// Fail safe rather than nil-deref: the backup-access branch inside
		// handleSTSTokenExchange reaches s.idpCaps.JWT at request time with
		// no earlier guard. This path is unreachable in production today —
		// the internal mTLS listener only mounts this handler in
		// regional, where idpCaps is always wired. Kept as
		// defense in depth per COR-858, matching OAuthTokenHandler's guard.
		// Checked here rather than inside handleSTSTokenExchange itself so
		// the public mux's own direct registration of that handler (the
		// HandleFunc in registerControlPlaneRoutes, called via
		// registerSessionAuthRoutes, likewise regional-only) is
		// untouched.
		if s.idpCaps == nil {
			http.Error(w, `{"error":"sts token endpoint not configured"}`, http.StatusServiceUnavailable)
			return
		}
		s.handleSTSTokenExchange(w, r)
	}
}

// OAuthTokenHandler returns the pkg/op /oauth/token handler so the
// internal mTLS listener can mount it alongside the legacy
// /api/authz/sts/token. Service-to-service callers (mirror-pipeline,
// peregrine) post RFC 8693 token-exchange requests here after COR-233
// drained the repo-access / ops-access branches off the legacy STS path.
//
// The subject_token still authorizes the exchange — the alternate
// listener's mTLS workload check is defence-in-depth, not the primary
// credential.
func (s *Server) OAuthTokenHandler() http.Handler {
	if s.idpCaps == nil {
		return http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
			http.Error(w, `{"error":"oauth token endpoint not configured"}`, http.StatusServiceUnavailable)
		})
	}
	return s.idpCaps.OIDCProvider
}

// crossJurisHint builds the AuthMiddleware hint from server state.
// Returns nil when there are no siblings or no AuthBaseURL configured
// (no cross-juris recovery is possible, so the middleware skips the
// structured hint and falls back to bare 401).
func (s *Server) crossJurisHint() *CrossJurisHint {
	if len(s.siblingAuthBaseURLs) == 0 || s.authBaseURL == "" {
		return nil
	}
	tokenURL := s.tokenEndpointURL
	if tokenURL == "" {
		tokenURL = strings.TrimRight(s.authBaseURL, "/") + "/oauth/token"
	}
	return &CrossJurisHint{
		SiblingAuthBaseURLs: s.siblingAuthBaseURLs,
		TokenExchangeURL:    tokenURL,
		LocalAuthBaseURL:    s.authBaseURL,
	}
}

// IsJurisdictionToken reports whether claims came from a jurisdiction
// token — i.e. its audience is the one the jurisdiction-token verifier
// pins. AuthMiddleware only ever produces such claims via that verifier
// (which pins aud exactly and requires scope=openid), so the audience
// match is a reliable discriminator.
//
// The /api/v1 mutation gate uses this to treat a jurisdiction token as a
// full principal: identity is proven, and SpiceDB authorizes every
// operation regardless of token shape. Returns false when no
// jurisdiction-token exchange is wired (nil verifier) or claims is nil.
func (s *Server) IsJurisdictionToken(claims *authn.Claims) bool {
	if s.jurisdictionVerifier == nil || claims == nil {
		return false
	}
	return slices.Contains(claims.Audiences, s.jurisdictionAudience)
}

// handleFederationManifest serves GET /.well-known/entire-federation.
// The body is the public allow-list a CLI uses to decide whether a 421
// redirect target (home_core_url) is in this core's federation — see
// internal/cliauth/cross_juris_transport.go. The list is not a secret
// (the same hosts appear in /api/info's jurisdiction map), so the
// endpoint is public.
//
// Returns an empty list when no siblings are configured (single-region,
// global, single-region regional). The CLI treats that as "no 421
// follow allowed from this origin" — defence-in-depth against an
// attacker setting up a hostile single-region core that returns 421
// with off-host home_core_url.
func (s *Server) handleFederationManifest(w http.ResponseWriter, r *http.Request) {
	hosts := s.siblingAuthBaseURLs
	if hosts == nil {
		hosts = []string{}
	}
	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("Cache-Control", "public, max-age=300")
	body := struct {
		PeerAuthHosts []string `json:"peer_auth_hosts"`
	}{PeerAuthHosts: hosts}
	if err := json.NewEncoder(w).Encode(body); err != nil {
		slogutil.Warn(r.Context(), "federation manifest encode failed", slog.String("error", err.Error()))
	}
}

func (s *Server) Handler() http.Handler {
	return s.wrapPublicChain(s.mux, "entire-core")
}

// wrapPublicChain applies the public middleware stack — auth (so claims
// reach request context, which downstream handlers gate on), logging, CORS,
// otel tracing with the matched-route span-name formatter, and the ENT-754
// security headers — around mux, then resolves the route pattern. Handler()
// and WrapPublicMux both route through here so the chain is defined in
// exactly one place. otelService is the span service name; mux is also
// passed to resolveRoutePattern so it can pre-resolve the matched pattern
// for the span formatter.
func (s *Server) wrapPublicChain(mux *http.ServeMux, otelService string) http.Handler {
	var h http.Handler = mux
	// The limiters are nil only on a Server built without NewServer (handler
	// unit tests); a nil limiter means "not wired", same as the struct's other
	// optional dependencies. NewServer always sets both, so production is
	// always limited.
	//
	// Per-principal limiting runs innermost, inside AuthMiddleware, so the
	// principal is on the context (and only for the authenticated API surface).
	if s.userRateLimit != nil {
		h = s.userRateLimitMiddleware(h)
	}
	// idpCaps groups Verifier/ConsoleSessionStore/ConsoleCookie/JWT (see
	// IdpCapabilities); the per-field OR below preserves the exact wrap
	// condition from before the group existed — a partial idpCaps (some
	// in-package tests wire only one of these) still wraps AuthMiddleware
	// exactly as a partial flat-field Config used to.
	if s.idpCaps != nil && (s.idpCaps.Verifier != nil || s.idpCaps.ConsoleSessionStore != nil) {
		h = AuthMiddleware(s.idpCaps.Verifier, s.jurisdictionVerifier, s.idpCaps.ConsoleSessionStore, s.idpCaps.ConsoleCookie, s.handleCache, s.platformAdminCache, s.crossJurisHint(), s.idpCaps.JWT)(h)
	}
	h = LogMiddleware(h)
	// Per-IP limiting is the outermost dispatch gate: after CORS/OTel (so
	// preflights and tracing aren't rate-limited) but before any handler runs.
	if s.ipRateLimit != nil {
		h = s.ipRateLimit.Middleware(h)
	}
	h = httputil.CORSMiddleware(h)
	h = setRouteAttr(h)
	h = otelhttp.NewHandler(h, otelService,
		otelhttp.WithSpanNameFormatter(matchedPatternSpanName),
	)
	h = securityHeaders(h)
	return resolveRoutePattern(mux, h)
}

// matchedPatternSpanName names a server span after the mux pattern
// resolveRoutePattern stashed up front (e.g. "GET /repos/{id}"), falling back
// to "<METHOD> [unmatched]" so unrouted requests stay low-cardinality.
func matchedPatternSpanName(_ string, r *http.Request) string {
	if pattern, _ := routePatternFromContext(r.Context()); pattern != "" {
		return pattern
	}
	return r.Method + " [unmatched]"
}

// TraceMuxHandler wraps mux in the same route-aware tracing stack
// wrapPublicChain applies — span names from the matched mux pattern (resolved
// up front, since otelhttp names the span before the mux dispatches) plus the
// http.route attribute recorded after dispatch, which is what lets the
// Datadog OTLP receiver derive a "<METHOD> <route>" resource instead of
// collapsing every request to its bare method. For extra listeners (the
// internal mTLS listener) whose muxes don't take the public auth/CORS chain.
func TraceMuxHandler(mux *http.ServeMux, otelService string) http.Handler {
	h := setRouteAttr(mux)
	h = otelhttp.NewHandler(h, otelService,
		otelhttp.WithSpanNameFormatter(matchedPatternSpanName),
	)
	return resolveRoutePattern(mux, h)
}

// resolveRoutePattern wraps the otelhttp layer so the matched mux pattern is
// available at span-creation time. otelhttp.NewHandler computes the span
// name in WithSpanNameFormatter before the inner handler runs, but Go's
// http.ServeMux only populates r.Pattern when it dispatches the matched
// handler — i.e. inside the otel handler. We resolve the pattern up front
// with mux.Handler (idempotent; no dispatch) and stash it on the context
// for the formatter to read. The mux still does its own routing as normal.
//
// It also seeds the RecordedRoute slot here — outermost, outside otelhttp — so
// a sub-router mounted under a catch-all (the huma API at "/api/v1/", whose
// per-operation route mux.Handler can't see up front) can record its matched
// route for setRouteAttr to prefer. The pointer survives the request clones the
// auth middleware makes, so the writer and reader share one slot.
func resolveRoutePattern(mux *http.ServeMux, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		ctx := WithRecordedRoute(r.Context())
		if _, pattern := mux.Handler(r); pattern != "" {
			ctx = withRoutePattern(ctx, pattern)
		}
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}

type routePatternKey struct{}

func withRoutePattern(ctx context.Context, pattern string) context.Context {
	return context.WithValue(ctx, routePatternKey{}, pattern)
}

func routePatternFromContext(ctx context.Context) (string, bool) {
	p, ok := ctx.Value(routePatternKey{}).(string)
	return p, ok
}

func (s *Server) domainAuditLog(r *http.Request, accountID model.AccountID, eventType, resourceType, resourceID string, meta map[string]any) {
	s.DomainAuditLog(r.Context(), accountID, eventType, resourceType, resourceID, meta)
}

// DomainAuditLog is the ctx-based counterpart to domainAuditLog for
// coreapi (huma) handlers that don't carry an *http.Request. Failures
// log a warning and are swallowed — audit writes are best-effort.
func (s *Server) DomainAuditLog(ctx context.Context, accountID model.AccountID, eventType, resourceType, resourceID string, meta map[string]any) {
	if s.domainAudit == nil {
		return
	}
	if err := s.domainAudit.Log(ctx, accountID, eventType, resourceType, resourceID, meta); err != nil {
		slogutil.Warn(ctx, "domain audit failed", slog.Any("error", err))
	}
}

func (s *Server) routes() {
	switch s.mode {
	case "global":
		s.registerGlobalRoutes()
	case "reaper":
		// The account-deletion reaper builds a *Server only to call
		// FinalizeAccountDeleteCore directly (ADR 20260707); it never serves
		// HTTP and wires none of the session/auth/IdP deps. Register only the
		// mode-agnostic common routes — registerSessionAuthRoutes would deref a
		// nil idpCaps.
		s.registerCommonRoutes()
	default:
		// "regional", plus the empty mode tests construct servers with.
		s.registerRegionalRoutes()
	}
}

func (s *Server) registerCommonRoutes() {
	s.mux.HandleFunc("GET /healthz", s.handleHealth)
	s.mux.HandleFunc("GET /api/info", s.handleInfo)
	// Federation manifest is mode-agnostic — every entire-core mode
	// publishes it, even if the list is empty. The CLI's 421-follow
	// trust gate calls this on every responding origin, so a missing
	// route would force it to refuse cross-juris redirects across the
	// whole fleet on a partial rollout.
	s.mux.HandleFunc("GET /.well-known/entire-federation", s.handleFederationManifest)
}

func (s *Server) registerAuthenticatedRoutes() {
	// Identity / audit / control-plane / service-account user-facing JSON
	// routes moved to /api/v1/* served by core/coreapi (see ADR
