// RepoBridge is the subset of core/repoadmin.Client used by the admin
// handlers and the provisioning reconciler — the control-plane bridge
// to entiredb. Interface-typed so the api package doesn't import
// repoadmin just for construction.
//
// clusterSlug names the destination entiredb cluster within this
// regional core's jurisdiction; the implementation routes the RPC to
// that cluster's :8281 listener. Required and must match a known
// cluster — the production wiring (repoadmin.Router) rejects unknown
// slugs with ErrUnknownCluster rather than falling back to a default.
type RepoBridge interface {
	Provision(ctx context.Context, repoID model.RepoID, clusterSlug, url, mirrorUpstreamURL string, mirrorAppInstallationID int64, objectFormat, repoGroupID, defaultBranch, nativeMirrorPrimaryURL, trustLifecycle string) error
	Delete(ctx context.Context, repoID model.RepoID, clusterSlug string) error
	MarkMirrorInitialSyncDone(ctx context.Context, repoID model.RepoID, clusterSlug string) error
	// GetTrustState reads a placement's current trust view from the data plane.
	// The native-mirror rooted-expansion capability fence
	// (ADR 20260724-rsl-root-of-trust-mvp) uses it to refuse expanding a repo
	// that has already rooted.
	GetTrustState(ctx context.Context, repoID model.RepoID, clusterSlug string) (repoadmin.TrustState, error)
}

// TrustReader reads read-only RSL trust state from the data plane for the
// admin trust card, dispatched by cluster slug. The production implementation
// is *repoadmin.Router; nil means no data-plane bridge is wired, so every
// trust read is reported as "status unavailable" rather than failing. Kept
// separate from RepoBridge so an older bridge that predates trust still
// satisfies RepoBridge without pretending to answer trust reads.
type TrustReader interface {
	GetTrustState(ctx context.Context, repoID model.RepoID, clusterSlug string) (repoadmin.TrustState, error)
	// ValidateTrustPublication runs the data plane's diagnostic publication
	// preflight, which reports the visible-ref inventory, estimated baseline,
	// workload class, and oversized classification. A passing result is never an
	// authorization to publish.
	ValidateTrustPublication(ctx context.Context, repoID model.RepoID, clusterSlug string, preflight repoadmin.TrustPreflight) (repoadmin.TrustPreflightResult, error)
	// GetTrustReceipt reads the durable publication receipt for (repo, operation),
	// whose verification baseline the card renders as the history boundary.
	GetTrustReceipt(ctx context.Context, repoID model.RepoID, clusterSlug, operationID string) (repoadmin.TrustReceipt, error)
	// GetTrustActivity reads a page of the repo's RSL reference entries (newest
	// first) for the admin console's recent-activity view.
	GetTrustActivity(ctx context.Context, repoID model.RepoID, clusterSlug string, pageSize int32, cursor string) (repoadmin.TrustActivityPage, error)
}

// TrustEnabler records a bootstrap trust intent for a repo and drives one
// reconcile pass to publish it (ADR 20260724-rsl-root-of-trust-mvp, slice 2).
// The production implementation lives in internal/entirecore, wiring
// nativemirror.EnsureBootstrapIntent + TrustReconciler.RunOnce. nil (the flag
// off, or dev/tests) means the admin enable-trust-root surface is not served.
type TrustEnabler interface {
	EnableTrustRoot(ctx context.Context, repoID model.RepoID) (TrustEnableResult, error)
}

// TrustEnableResult is the outcome of an enable-trust-root request.
type TrustEnableResult struct {
	// OperationID is the durable intent's operation id (idempotency key).
	OperationID string
	// Created is true when this call inserted a new intent, false on an
	// idempotent replay of an existing active or published one.
	Created bool
	// Provisioned is true when the reconciler is wired (fleet root profile +
	// seed present) and a publish was attempted; false when the intent was
	// recorded but the environment cannot publish yet.
	Provisioned bool
	// Drained is true when the reconcile pass claimed and progressed an intent.
	Drained bool
	// State is the intent's lifecycle state after the enable flow (a
	// nativemirror IntentState*): the creation state when unprovisioned, or the
	// post-drive outcome (published / failed / still pending) when provisioned.
	// Empty when it could not be read.
	State string
}

// ErrTrustNotOwningJurisdiction is returned by EnableTrustRoot when this core
// does not own the repo's primary placement jurisdiction. The owning core is the
// sole orchestration owner (ADR 20260724), so the caller must retarget it.
var ErrTrustNotOwningJurisdiction = errors.New("api: repo is not homed in this core's jurisdiction")

// TrustIntentReader reads a repo's trust-publication intents for the admin trust
// card's operational section: the control-plane record of each bootstrap or
// backfill attempt and its retry/pause status (state, attempts, next retry,
// pause reason). *nativemirror.Service implements it; nil omits the section.
// This is Core's own desired-state record, deliberately distinct from the signed
// data-plane state TrustReader returns, so the card can show a paused or
// retrying intent that has not yet reached rooted.
type TrustIntentReader interface {
	TrustIntentsForRepo(ctx context.Context, repoID model.RepoID) ([]nativemirror.TrustIntent, error)
	// PlacementAcceptancesForRepo reads Core's per-placement acceptance records
	// for the slice-4 placement matrix: which mirror placements have accepted a
	// published operation, which are behind, and which are quarantined.
	PlacementAcceptancesForRepo(ctx context.Context, repoID model.RepoID) ([]nativemirror.PlacementAcceptance, error)
}

// UnconfiguredBridge is the RepoBridge stand-in for every deployment
// where no live data-plane bridge is available: Config.RepoBridge nil
// (dev/tests), global mode (no cluster store), a jurisdiction with zero
// active clusters, or no internal mTLS client for cnf-bound tokens
// (dev). Provision/Delete return repoadmin.ErrNotConfigured
// wrapping Reason; handlers route that through their normal
// bridge-unavailable path (create keeps the row in provisioning for the
// reconciler; delete falls back to core-only cleanup). The reconciler
// recognises this type and idles rather than looping errors (COR-857).
type UnconfiguredBridge struct{ Reason string }

// NewUnconfiguredBridge builds the stand-in with a human reason for logs.
func NewUnconfiguredBridge(reason string) UnconfiguredBridge {
	return UnconfiguredBridge{Reason: reason}
}

func (b UnconfiguredBridge) Provision(context.Context, model.RepoID, string, string, string, int64, string, string, string, string, string) error {
	return fmt.Errorf("%w: %s", repoadmin.ErrNotConfigured, b.Reason)
}

func (b UnconfiguredBridge) GetTrustState(context.Context, model.RepoID, string) (repoadmin.TrustState, error) {
	return repoadmin.TrustState{}, fmt.Errorf("%w: %s", repoadmin.ErrNotConfigured, b.Reason)
}

func (b UnconfiguredBridge) Delete(context.Context, model.RepoID, string) error {
	return fmt.Errorf("%w: %s", repoadmin.ErrNotConfigured, b.Reason)
}

func (b UnconfiguredBridge) MarkMirrorInitialSyncDone(context.Context, model.RepoID, string) error {
	return fmt.Errorf("%w: %s", repoadmin.ErrNotConfigured, b.Reason)
}

func repoBridgeOrUnconfigured(b RepoBridge) RepoBridge {
	if b == nil {
		return NewUnconfiguredBridge("Config.RepoBridge was nil")
	}
	return b
}

// GitHubInstallationMinter is the contract the STS handler uses to mint
// GitHub App installation tokens. *githubapp.AppClient satisfies it for
// production; tests inject a fake.
//
// Exported so wireAPIServer can declare its local as the interface type
// and never carry a typed-nil concrete pointer into Config — assigning a
// nil concrete to an interface field produces a non-nil interface, which
// would silently defeat the handler's `s.ghAppCaps == nil` check.
type GitHubInstallationMinter interface {
	// InstallationToken mints (or serves from a Core-side cache) a
	// repository-scoped GitHub App installation token. fromCache reports
	// whether the token was served without a GitHub API call for this
	// request (a cache hit or a coalesced concurrent miss), so the handler's
	// audit log can distinguish a fresh mint from a reused token (COR-596).
	InstallationToken(ctx context.Context, installationID int64, repo string) (token string, expiresAt time.Time, fromCache bool, err error)
	// InstallationTokenForPush is the write-scoped counterpart used only for
	// an authorized entiredb mirror push-through request.
	InstallationTokenForPush(ctx context.Context, installationID int64, repo string) (token string, expiresAt time.Time, fromCache bool, err error)
	// InstallationTokenForChecks mints a repo-read + checks:read token, used by
	// entire-api's trail-gate checks evaluation to read GitHub check-runs. Kept
	// separate from InstallationToken so the checks scope is cache-isolated and
	// a plain-read caller can never receive it.
	InstallationTokenForChecks(ctx context.Context, installationID int64, repo string) (token string, expiresAt time.Time, fromCache bool, err error)
	// InstallationTokenForChecksWrite mints a repo-read + checks:write token,
	// used by entire-api to publish the trail-gates rollup as a check run.
	// Kept separate from InstallationTokenForChecks so a read caller can never
	// be widened into a writer.
	InstallationTokenForChecksWrite(ctx context.Context, installationID int64, repo string) (token string, expiresAt time.Time, fromCache bool, err error)
	// InstallationTokenForPullRequests mints a repo-read + pull_requests:write
	// token, used by entire-api to prepend the trail backlink to a PR body. It
	// grants no contents write.
	InstallationTokenForPullRequests(ctx context.Context, installationID int64, repo string) (token string, expiresAt time.Time, fromCache bool, err error)
}

// MirrorBootstrapper establishes the installation + github_repos rows
// for one (owner, repo) from the App's own credential. It writes no
// access edges — mirror authz lives in SpiceDB (COR-437); these rows
// only carry the installation_id the inbound-sync token mint and
// mirror-create lookups read.
//
// *permssnapshotter.Snapshotter satisfies this contract in production;
// tests inject a fake. Declared as an interface here for the same
// typed-nil safety reason as GitHubInstallationMinter — a nil concrete
// behind a non-nil interface would silently bypass the handler's
// "bootstrap not configured" 503 path.
type MirrorBootstrapper interface {
	// EnsureRepoKnown upserts the installation + github_repos rows from
	// the App's credential and returns the github_repo_id, the repo's
	// visibility, GitHub's canonical owner/repo casing, and its default
	// branch off the GitHub object it just persisted (so the create path can
	// seed SpiceDB visibility, the display full name, and the data-plane HEAD
	// without re-reading its own write). It does not gate on the caller's
	// access (that's authorizeUserMirrorCreate's job), only on the App being
	// installed upstream.
	EnsureRepoKnown(ctx context.Context, owner, repo string, observedAt time.Time) (githubRepoID int64, isPrivate bool, ownerLogin, repoName, defaultBranch string, err error)
	// RefreshRepoCollaborators re-snapshots the repo's collaborator read-model
	// from the live GitHub API and returns the github_repo_id. Used by resume to
	// reconcile against current GitHub truth.
	RefreshRepoCollaborators(ctx context.Context, owner, repo string, observedAt time.Time) (githubRepoID int64, err error)
}

// MirrorPermsBackfillPublisher enqueues an asynchronous job to reconcile all of
// a mirrored upstream's GitHub collaborators into SpiceDB, OFF the mirror-create
// request path. The creating user's own grant is written synchronously
// (grantMirrorCreator), so the backfill materialises everyone else; the periodic
// perms reconciler is the authoritative backstop if a job is lost. Optional — a
// nil publisher (e.g. dev without NATS) degrades to that reconciler.
type MirrorPermsBackfillPublisher interface {
	PublishBackfill(ctx context.Context, jurisdiction, clusterSlug string, githubRepoID int64) error
}

// MirrorSourceSizer reports an upstream repository's on-disk size at GitHub so
// mirror-create can reject a source that could never finish its initial sync
// push (see mirror_source_size.go). *githubgraphql.Client satisfies it; tests
// inject a fake. Optional — when the containing GitHubAppCapabilities leaves it
// nil, or any lookup fails, the create proceeds unguarded (fail open).
type MirrorSourceSizer interface {
	// RepoDiskUsageKiB returns GitHub's reported on-disk size of owner/repo in
	// kibibytes, using an installation access token. known is false when GitHub
	// reports no size (a null diskUsage, e.g. an empty repository).
	RepoDiskUsageKiB(ctx context.Context, token, owner, repo string) (kib int64, known bool, err error)
}

// Server is the HTTP API for entire-core. Its fields fall into three
// buckets — the census a new field should join deliberately, not get
// bolted onto loose (COR-832):
//
//  1. Core: dependencies and config knobs wired in every mode regardless
//     of jurisdiction or capability gating — mux, identity, authz,
//     resource, providers, githubPerms, githubUserAPI, mirrorRepos,
//     lifecycleEvents, the handle/platform-admin caches, oauthStateStore,
//     the jurisdiction*Hosts maps, rate limiters, and the string/bool
//     config fields (mode, jurisdiction, authBaseURL, and friends).
//
//  2. Four capability groups, each all-or-nothing (see the matching
//     New*Capabilities constructor: every field non-nil or a boot
//     error) and nil exactly when the owning mode does not wire it:
//     - routerCaps (RouterCapabilities) — global only.
//     - ghAppCaps (GitHubAppCapabilities) — any mode, gated on the
//     GitHub App being configured.
//     - jurCaps (JurisdictionCapabilities) — regional;
//     never global, which is the COR-730 incident-#1 guarantee
//     (RunReconciler hangs off this group, so global cannot
//     construct, let alone start, the reconciler).
//     - idpCaps (IdpCapabilities) — regional; never
//     global, which issues no sessions of its own.
//
//  3. Named top-level optionals that belong to no group, each with its
//     own independent gate:
//     - workos — nil disables the SSO endpoints (SSO-off-when-nil).
//     - githubTokens — nil until the token cipher is configured
//     (cipher-gated).
//     - cookie — nil until the home-jurisdiction cookie secret is
//     configured (secret-gated).
//     - jurisdictionVerifier, siblingAuthBaseURLs — cross-jurisdiction-
//     adjacent but each independently gated.
//     - clusterAdminTransport, internalTokenEndpoint,
//     internalTokenClient — the cluster-admin-proxy trio, gated
//     together on TLS config being present.
//     - analytics — nil-tolerant; every method on a nil client is a
//     no-op.
//     - erasureOutbox — nil-tolerant multi-region account-erasure
//     enqueuer; nil (e.g. account deletion not launched) skips the
//     fan-out enqueue rather than failing the delete.
//     - emailOutbox — nil-tolerant transactional-email enqueuer; nil
//     (e.g. email sending disabled) skips the enqueue rather than
//     failing the triggering operation.
//     - mirrorPermsBackfill — soft-degrade optional, deliberately
//     demoted out of JurisdictionCapabilities (see jurCaps below):
//     nil falls back to the periodic reconciler.
//     - regional, cluster, gitJobsPub — mirrored off jurCaps one-
//     for-one purely for read convenience at the many existing
//     direct call sites; always set together, nil together, never
//     independently gated.
type Server struct {
	mux         *http.ServeMux
	identity    identity.Service
	handleCache *HandleStateCache
	// platformAdminCache memoizes platform-admin checks for the admin SPA
	// bundle gate only (ENT-755). Not used by the admin API handlers,
	// which stay live/uncached.
	platformAdminCache *platformAdminCache
	// jurisdictionVerifier accepts the jurisdiction token on the /api/v1
	// resource surface only — see AuthMiddleware. nil disables
	// jurisdiction-token acceptance (single-host dev).
	jurisdictionVerifier *jwtverify.Verifier
	// jurisdictionAudience is the exact audience jurisdictionVerifier pins;
	// IsJurisdictionToken classifies against it. Empty when
	// jurisdictionVerifier is nil.
	jurisdictionAudience string
	// siblingSubjectVerifiers verifies github-access-token exchange
	// subjects a sibling core minted, keyed by the sibling's iss (its
	// AuthBaseURL). Built from SiblingAuthBaseURLs — the same trust set
	// the oidcop dispatcher uses for cross-juris subject_token validation.
	// It admits the legacy repo-scoped push credential (COR-941) and the
	// sibling's self-audienced account access token (COR-1111); the handler
	// classifies the verified shape. nil when no siblings are configured
	// (single-region).
	siblingSubjectVerifiers *jwtverify.TrustedIssuers
	authz                   authz.Service
	regional                regional.Service
	resource                resource.Service
	automation              automation.Service
	erasureOutbox           ErasureEnqueuer
	erasureLedger           *erasureledger.Store
	emailOutbox             EmailEnqueuer
	// ceoWelcomeEnabled mirrors Config.CEOWelcomeEnabled — see there.
	ceoWelcomeEnabled bool
	cluster           *cluster.Store
	providers         *authn.ProviderRegistry
	githubTokens      *githubtokens.Service
	githubPerms       *githubperms.Service
	// oidcFed + domainAudit were formerly bundled in idpCaps; lifted to
	// top-level so non-auth-host cores (global) and the account-deletion reaper
	// can wire them without the full auth-login stack. See ADR 20260707.
	oidcFed       oidcfed.Service
	domainAudit   *audit.DomainAudit
	githubUserAPI GitHubUserInstallationsAPI
	userPermsSync UserPermsSyncer
	// availableMirrorsReadModel, when true, serves GET /api/v1/mirrors/available
	// from the local github_user_repo_access read-model once the selected gate
	// clears. Off keeps the original live-GitHub path. NOT an authz toggle.
	availableMirrorsReadModel bool
	availableMirrorsUserFresh bool
	permsUserSyncTTL          time.Duration
	// availableMirrorsPerms is githubPerms behind the readiness-gate TTL cache
	// (see mirrors_available_readiness_cache.go); the /mirrors/available serve
	// path reads through this, everything else keeps the uncached service.
	// nil iff githubPerms is nil.
	availableMirrorsPerms availableMirrorsReadModelSource
	// githubTokenIdentityExchange gates the jurisdiction-token subject shape on
	// the STS github-access-token exchange (COR-813). Off = repo-push only.
	githubTokenIdentityExchange bool
	mirrorRepos                 *mirrorrepo.Service
	mirrorRequests              *mirrorrequest.Store
	mirrorRequestPublisher      mirrorrequest.Publisher
	nativeMirrors               *nativemirror.Service
	nativeMirrorEnabled         bool
	nativeMirrorCreateEnabled   bool
	gitJobsPub                  *gitjobs.Publisher
	// resyncPub publishes a synthetic GitHub push webhook to the central
	// webhooks_github_v1 stream to trigger a mirror-pipeline resync (ENT-1172).
	// Optional — nil (e.g. no NATS configured) makes ResyncMirror return
	// ErrResyncUnavailable, which handlers map to 503. See ResyncPublisher.
	resyncPub       ResyncPublisher
	lifecycleEvents *resourceevents.Emitter
	analytics       *analytics.Client
	// ghAppCaps is everything minted from the configured GitHub App key
	// (STS minter, admin checker, mirror bootstrapper). nil when
	// ENTIRE_GITHUB_APP_ID is unset — see GitHubAppCapabilities.
	ghAppCaps           *GitHubAppCapabilities
	mirrorPermsBackfill MirrorPermsBackfillPublisher
	// workos is optional — nil disables the SSO endpoints. Enable by
	// providing a configured *workos.Service.
	workos                 *workos.Service
	githubClientID         string
	githubClientSecret     string
	githubRedirectURL      string            // OAuth callback URL registered with GitHub
	githubAppPublicURL     string            // public "install the App" URL surfaced to users (empty → prod default)
	authBaseURL            string            // IdP/auth origin (issuer, audience, /api/auth/*, /cli/auth)
	consoleURL             string            // user-facing console UI origin (post-login, /logged-out)
	ciWebhooksURL          string            // entire-ci-webhooks leaf public URL (ops-token audience + dial base); empty where unreachable
	ciWebhooksURLs         map[string]string // cluster slug -> that cell's ci-webhooks URL; empty means every placement uses ciWebhooksURL
	firstPartyOrigins      []string          // extra first-party SPA origins for /oauth/token allowlist (COR-361)
	primaryLoginURL        string            // front-door login URL (e.g. https://partial.to/login); empty in single-host dev
	mode                   string            // "global", "regional" (or "reaper" / "" in internal wiring and tests)
	jurisdiction           string            // "us", "eu" (regional only)
	deployEnv              string            // staging or production (empty in local dev)
	accountDeletionEnabled bool              // launch gate for self-service account deletion

	cookie            *authn.HomeJurisdictionCookie
	oauthStateStore   *authn.OAuthStateStore
	jurisdictionHosts map[string]string
	// jurisdictionAuthHosts maps each jurisdiction to its OIDC issuer URL.
	// Read by every cross-jurisdiction redirect whose target is on the
	// auth host. Populated by entirecore.MergeAuthHosts, which per-key
	// falls back to jurisdictionHosts; the fallback is safe while auth
	// and console DNS terminate on the same backend.
	// TODO(COR-256): drop the fallback in entirecore once every overlay
	// sets JURISDICTION_AUTH_HOSTS.
	jurisdictionAuthHosts map[string]string
	// jurisdictionAPIHosts maps each jurisdiction to its entire-api base URL
	// (the cell-bound data API). Surfaced per-jurisdiction on GET
	// /api/v1/clusters (Cluster.apiUrl). Plain addressing — no auth/trust
	// role and no console-host fallback — so an unset jurisdiction simply
	// reports an empty apiUrl.
	jurisdictionAPIHosts map[string]string
	// entireAPIInternalURL is THIS cell's entire-api internal mTLS listener base
	// URL, dialled by the cell-state admin proxy (handleAdminRepoCellState).
	entireAPIInternalURL string
	// siblingAuthBaseURLs is the federated peer list emitted on
	// /.well-known/entire-federation. Populated only from the raw
	// JURISDICTION_AUTH_HOSTS map (never the console-host fallback),
	// minus the local AuthBaseURL — so the CLI sees the same trust set
	// the oidcop dispatcher uses for cross-juris subject_token
	// validation. Empty / nil in modes where cross-juris isn't wired.
	siblingAuthBaseURLs []string

	// routerCaps is the global-mode front-door surface (the home-jurisdiction
	// router). nil on regional servers — see RouterCapabilities.
	routerCaps *RouterCapabilities

	// jurCaps is the jurisdiction-bound data-plane surface (regional store,
	// cluster fixture, entiredb bridge, git-jobs publisher, plus a duplicate
	// resource reference) that regional wires as a unit and global
	// cannot construct at all — see JurisdictionCapabilities. nil on global
	// servers. The provisioning-reconciler subsystem (COR-832) is built from
	// this value, never from the Server directly, which is what makes a
	// global server structurally unable to start it (the COR-730 incident-#1
	// guarantee).
	//
	// regional, cluster, and gitJobsPub below mirror jurCaps's fields
	// one-for-one (set together at construction, nil together) so the many
	// existing call sites that read them directly are untouched by this
	// group's introduction; only the handler-boundary nil-checks that used to
	// gate on those fields individually now gate on jurCaps.
	jurCaps *JurisdictionCapabilities

	// waitlistMode gates new-account approval at creation across any
	// self-service signup path the global server owns (none today — account
	// creation is regional). Mirrors loginflow.Flow.waitlistMode: when true, fresh accounts
	// are created unapproved (approved=false) and stay waitlisted until an admin
	// approves them. See ADR 20260618-waitlist-approval-gate.
	waitlistMode bool

	// idpCaps is the identity-provider surface (login flow, JWT issuer, key
	// store, verifier, pkg/op provider, every session store/cookie pair,
	// auth-request bridge, client registry, device-grant store, system
	// login, service account, oidcfed, token-endpoint client, domain audit)
	// that regional wires as a unit and global cannot construct at
	// all — see IdpCapabilities. nil on global servers.
	idpCaps *IdpCapabilities

	// frontendFS powers the device-flow browser approval page. Nil-tolerant:
	// the device flow returns 503 server_error when missing, so a
	// deployment that hasn't wired it up doesn't break unrelated routes.
	frontendFS fs.FS

	// tokenEndpointURL is the IdP's /api/auth/token URL as seen from the RP
	// side. In single-binary deployments the IdP and RP are the same
	// process, but the call still goes over HTTP so the trust boundary is
	// enforced by client_id/secret, not by DB sharing. The client built
	// from it lives on idpCaps.TokenEndpointClient.
	tokenEndpointURL string

	// repoBridge is the entiredb RepoAdmin client used by handleCreateRepo,
	// handleAdminDeleteRepo, and the provisioning reconciler. Declared as
	// an interface so tests can inject fakes.
	repoBridge RepoBridge

	// trustReader reads read-only trust state for the admin trust card; nil
	// (no data-plane bridge) renders every read as "status unavailable".
	// clusterFixtureEnv selects the fixture the fleet root profile is read
	// from for that card.
	trustReader       TrustReader
	trustEnabler      TrustEnabler
	trustIntents      TrustIntentReader
	clusterFixtureEnv string

	// allowedClusterDomain is the suffix every `cluster` and `return_to`
	// host must match for /api/authz/debug-bounce (e.g. "partial.to").
	// Empty disables the bounce endpoint.
	allowedClusterDomain string

	// handoffReturnToHosts is the exact-host allowlist for `return_to` on
	// GET /api/auth/resolve-jurisdiction (e.g. the entire.io BFF's callback
	// host). Empty disables the endpoint.
	handoffReturnToHosts []string

	// loginStartURL is the BFF's jurisdictional login-start URL. The global
	// router bounces here when it can't complete a handback (invalid/expired
	// state), and its origin is the bare-root redirect target. Empty disables
	// both (callers degrade to the auth error page / landing).
	loginStartURL string

	// clusterAdminTransport is the mTLS transport the cluster-admin
	// proxy dials entiredb with. Nil leaves the proxy disabled.
	clusterAdminTransport *http.Transport

	// internalTokenEndpoint and internalTokenClient drive the cluster-
	// admin proxy's on-behalf-of token mint: a loopback mTLS POST to
	// this core's own /oauth/token so the issued JWT's cnf binds to
	// entire-core's client leaf at mint time (COR-337). Mirrors the
	// repoadmin BearerTransport wiring; empty/nil falls the proxy back
	// to the in-process IssueOpsToken signer.
	internalTokenEndpoint string
	internalTokenClient   *http.Client

	// ipRateLimit enforces tiered per-IP limits (global + stricter auth +
	// tightest system-login) over the whole public chain; userRateLimit
	// enforces per-principal limits on the authenticated /api/v1 and
	// /api/admin surface. Both are no-ops in test mode. See ratelimit.go.
	ipRateLimit   *ratelimit.HTTPLimiter
	userRateLimit *ratelimit.Limiter
	// stsRateLimit throttles /api/authz/sts/token per verified subject account
	// inside handleGitHubAccessTokenExchange (COR-937): on the dominant
	// BFF-mediated path core sees only the shared Cloudflare egress IP so IP
	// keying can't separate users, and per-verified-subject keying is the right
	// identity for that path and the non-BFF mirror-push flow alike. No-op in
	// test mode. See ratelimit.go.
	stsRateLimit *ratelimit.Limiter

	oauthMu     sync.Mutex
	oauthStates map[string]oauthState // CSRF state → metadata
}

type oauthState struct {
	expiry        time.Time
	payload       string
	provider      string
	authRequestID string
}

const oauthStateTTL = 10 * time.Minute

func defaultConsoleClientID(clientID string) string {
	if clientID == "" {
		return "console"
	}
	return clientID
}

