// --- Token validation ---

func (s *Server) handleValidateToken(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Token        string `json:"token"`
		Action       string `json:"action"`
		ResourceType string `json:"resource_type"`
		ResourceID   string `json:"resource_id"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil || req.Token == "" {
		http.Error(w, `{"error":"provide token"}`, http.StatusBadRequest)
		return
	}
	authzRequested := req.Action != "" || req.ResourceType != "" || req.ResourceID != ""
	if authzRequested && (req.Action == "" || req.ResourceType == "" || req.ResourceID == "") {
		http.Error(w, `{"error":"provide action, resource_type, and resource_id together"}`, http.StatusBadRequest)
		return
	}

	claims, err := authn.VerifyClaims(r.Context(), s.idpCaps.Verifier, req.Token)
	if err != nil {
		if errors.Is(err, authn.ErrJWKSUnavailable) {
			writeErr(w, r, http.StatusServiceUnavailable, errors.New("jwks_unavailable"))
			return
		}
		writeJSON(w, http.StatusOK, map[string]any{
			"valid":  false,
			"reason": validateTokenFailureReason(err),
		})
		return
	}

	if s.identity == nil {
		writeErr(w, r, http.StatusServiceUnavailable, errors.New("identity unavailable"))
		return
	}
	if _, err := s.identity.GetAccount(r.Context(), claims.AccountID); err != nil {
		if errors.Is(err, identity.ErrNotFound) {
			writeJSON(w, http.StatusOK, map[string]any{
				"valid":  false,
				"reason": "account_not_found",
			})
			return
		}
		writeErr(w, r, http.StatusServiceUnavailable, fmt.Errorf("validate account: %w", err))
		return
	}

	resp := map[string]any{
		"valid":            true,
		"jti":              claims.JTI,
		"account_id":       claims.AccountID,
		"handle":           claims.Handle,
		"provider":         claims.Provider,
		"provider_user_id": claims.ProviderUserID,
	}
	if authzRequested {
		if s.authz == nil {
			writeErr(w, r, http.StatusServiceUnavailable, errors.New("authz unavailable"))
			return
		}
		allowed, err := s.authz.Can(r.Context(),
			"account:"+claims.AccountID.String(),
			req.Action,
			req.ResourceType+":"+req.ResourceID,
		)
		if err != nil {
			writeErr(w, r, http.StatusServiceUnavailable, fmt.Errorf("authz check: %w", err))
			return
		}
		resp["authorized"] = allowed
	}
	writeJSON(w, http.StatusOK, resp)
}

func validateTokenFailureReason(err error) string {
	switch {
	case errors.Is(err, josejwt.ErrInvalidAudience):
		return "audience"
	case errors.Is(err, josejwt.ErrExpired):
		return "expired"
	case errors.Is(err, josejwt.ErrNotValidYet):
		return "not_yet_valid"
	default:
		return "signature"
	}
}

