)

// SubmitMirrorRequest authorizes and queues an asynchronous mirror placement.
func (s *Server) SubmitMirrorRequest(ctx context.Context, claims *authn.Claims, provider, owner, repo, clusterHost string) (mirrorrequest.CreateResult, error) {
	ctx, span := otel.Tracer(tracerName).Start(ctx, "mirror.request.submit")
	outcome := mirrorRequestSubmissionFailed
	defer func() {
		recordMirrorRequestSubmission(ctx, s.jurisdiction, outcome)
		if !mirrorRequestSubmissionAccepted(outcome) {
			span.SetStatus(codes.Error, outcome)
		}
		span.End()
	}()

	if claims == nil {
		outcome = mirrorRequestSubmissionUnauthenticated
		return mirrorrequest.CreateResult{}, &MirrorOpError{Status: http.StatusUnauthorized, Message: "unauthenticated"}
	}
	if s.mirrorRequests == nil || s.mirrorRequestPublisher == nil {
		outcome = mirrorRequestSubmissionUnavailable
		return mirrorrequest.CreateResult{}, &MirrorOpError{Status: http.StatusServiceUnavailable, Message: "mirror requests are not available"}
	}
	if s.mirrorRepos == nil {
		outcome = mirrorRequestSubmissionUnavailable
		return mirrorrequest.CreateResult{}, &MirrorOpError{Status: http.StatusServiceUnavailable, Message: "mirror service not configured"}
	}

	req := mirrorOpRequest{Provider: provider, Owner: owner, Repo: repo, ClusterHost: clusterHost}
	owner, repo, status, err := req.validate()
	if err != nil {
		outcome = mirrorRequestSubmissionInvalid
		return mirrorrequest.CreateResult{}, &MirrorOpError{Status: status, Message: err.Error()}
	}

	clusterSlug, jurisdiction, _, status, err := s.resolveClusterHost(ctx, clusterHost)
	if err != nil {
		outcome = mirrorRequestSubmissionInvalid
		return mirrorrequest.CreateResult{}, &MirrorOpError{Status: status, Message: err.Error()}
	}
	if operationErr := s.jurisdictionRedirect(jurisdiction); operationErr != nil {
		outcome = mirrorRequestSubmissionWrongJurisdiction
		return mirrorrequest.CreateResult{}, operationErr
	}

	githubUserID, status, err := s.requireGitHubUser(ctx, claims.AccountID)
	if err != nil {
		outcome = mirrorRequestSubmissionGitHubIdentity
		return mirrorrequest.CreateResult{}, &MirrorOpError{Status: status, Message: err.Error()}
