func (s *Server) lookupOrDiscoverGitHubRepoID(ctx context.Context, owner, repo string) (int64, *MirrorOpError) {
	githubRepoID, err := s.githubPerms.LookupRepoIDByCoords(ctx, owner, repo)
	if err == nil {
		return githubRepoID, nil
	}
	if !errors.Is(err, githubperms.ErrRepoNotKnown) {
		return 0, &MirrorOpError{Status: http.StatusInternalServerError, Message: "github perms lookup", cause: err}
	}
	if s.ghAppCaps == nil || s.ghAppCaps.Bootstrapper == nil {
		return 0, &MirrorOpError{Status: http.StatusServiceUnavailable, Message: "mirror bootstrapper not configured"}
	}
	githubRepoID, _, _, _, _, err = s.ghAppCaps.Bootstrapper.EnsureRepoKnown(ctx, owner, repo, time.Now())
	if err != nil {
		return 0, s.mapBootstrapError(ctx, owner, repo, err, true)
	}
	return githubRepoID, nil
}

// GetMirrorRequest returns a request only to the account that submitted it.
func (s *Server) GetMirrorRequest(ctx context.Context, claims *authn.Claims, id uuid.UUID) (mirrorrequest.Request, error) {
	ctx, span := otel.Tracer(tracerName).Start(ctx, "mirror.request.get")
	outcome := "failed"
	defer func() {
		span.SetAttributes(attribute.String("mirror_request.read_outcome", outcome))
		if outcome == "failed" {
			span.SetStatus(codes.Error, outcome)
		}
		span.End()
	}()

	if claims == nil {
		outcome = "unauthenticated"
		return mirrorrequest.Request{}, &MirrorOpError{Status: http.StatusUnauthorized, Message: "unauthenticated"}
	}
	if s.mirrorRequests == nil {
		outcome = "unavailable"
		return mirrorrequest.Request{}, &MirrorOpError{Status: http.StatusServiceUnavailable, Message: "mirror requests are not available"}
	}
	request, err := s.mirrorRequests.GetForAccount(ctx, id, claims.AccountID)
	if errors.Is(err, mirrorrequest.ErrNotFound) {
		outcome = "not_found"
		return mirrorrequest.Request{}, &MirrorOpError{Status: http.StatusNotFound, Message: "mirror request not found"}
	}
	if err != nil {
		return mirrorrequest.Request{}, &MirrorOpError{Status: http.StatusInternalServerError, Message: "get mirror request", cause: err}
	}
	outcome = "found"
	return request, nil
}

