		if repo.Forge == resource.ForgeGitHub {
			githubForgeRepoIDs = append(githubForgeRepoIDs, repo.ForgeRepoID)
			githubPlacementIDs = append(githubPlacementIDs, repo.RepresentativePlacementID)
		} else {
			nativeGroupIDs = append(nativeGroupIDs, repo.ID)
		}
	}

	// Visibility failures are fatal for the request: a wrong private badge on
	// a public repo is the silent-lie failure mode this endpoint must not have.
	// Scoped to entire-forge rows only — a github-forge row's visibility comes
	// from github_repos below, never SpiceDB.
	publicGroupIDs := map[model.RepoGroupID]bool{}
	if len(nativeGroupIDs) > 0 {
		var err error
		publicGroupIDs, err = s.authz.PublicRepoGroupIDs(ctx, nativeGroupIDs)
		if err != nil {
			return nil, fmt.Errorf("resolve repo visibility: %w", err)
		}
	}

	// Fatal for the same reason as the native path above: a lookup failure
	// that fell back to the default "private" would silently under-report
	// exposure for every github-forge row on the page, not just leave a gap.
	githubRepos := map[string]resource.GitHubRepoInfo{}
	if len(githubForgeRepoIDs) > 0 {
		var err error
		githubRepos, err = s.resource.GetGitHubReposByForgeRepoIDs(ctx, githubForgeRepoIDs)
		if err != nil {
			return nil, fmt.Errorf("resolve github repo visibility: %w", err)
		}
	}

	// The Clone URL is NOT reconstructed from live github_repos coordinates
	// like origin/owner above: after an upstream rename, github_repos updates
	// immediately but the actual clonable /gh/ alias in github_mirror_repo_urls
	// lags until ReconcileURLAliases runs, so a reconstruction can 404 during
	// that window. Read the real persisted alias instead, via the same
	// representative placement id the Mirrors tab already keys this off of.
	// Best-effort: a lookup failure leaves the Clone URL blank, matching the
	// Mirrors tab's own best-effort treatment of the same query.
	mirrorURLs := map[model.RepoID]string{}
	if s.mirrorRepos != nil && len(githubPlacementIDs) > 0 {
		if origins, err := s.mirrorRepos.MirrorOriginsByIDs(ctx, githubPlacementIDs); err != nil {
			slogutil.Error(ctx, "backfill mirror clone urls for repos list", slog.Any("error", err))
		} else {
			for _, o := range origins {
				mirrorURLs[o.ID] = o.URL
			}
		}
	}

	items := make([]repoItem, 0, len(rows))
	for _, repo := range rows {
		// A missing org join leaves OrgID zero; serialize that as "" rather than
		// the all-zero ULID so the UI's "no org" case stays an empty string.
		orgID := ""
		if !repo.OrgID.IsZero() {
			orgID = repo.OrgID.String()
		}
		item := repoItem{
			ID:              repo.ID.String(),
			Name:            repo.Name,
			PlacementCount:  repo.PlacementCount,
			OwningProjectID: repo.OwningProjectID.String(),
			ProjectName:     repo.ProjectName,
			OrgID:           orgID,
			OrgName:         repo.OrgName,
			OrgGitHubLogin:  repo.OrgGitHubLogin,
			URL:             repo.URL,
			Visibility:      "private",
		}
		if repo.Forge == resource.ForgeGitHub {
			if info, ok := githubRepos[repo.ForgeRepoID]; ok {
				if !info.IsPrivate {
					item.Visibility = "public"
				}
				item.URL = mirrorURLs[repo.RepresentativePlacementID]
				item.OriginURL = mirrorrepo.UpstreamURL(info.OwnerLogin, info.RepoName)
				item.OwnerName = info.OwnerLogin
				// Only assert a type we actually know — an absent installation /
				// account_type leaves OwnerType blank rather than guessing gh:user.
				switch info.AccountType {
				case "Organization":
					item.OwnerType = "gh:org"
				case "User":
					item.OwnerType = "gh:user"
				}
			}
		} else {
			if publicGroupIDs[repo.ID] {
				item.Visibility = "public"
			}
			switch repo.ProjectOwnerType {
			case "org":
				item.OwnerType = "org"
				// Prefer the GitHub login for a gh-linked org (so it reads
				// "octocat", not the cryptic "gh:<id>" system name).
				item.OwnerName = cmp.Or(repo.OrgGitHubLogin, repo.OrgName)
			case "account":
				item.OwnerType = "account"
				// OwnerName filled in below once handles resolve.
			}
		}
		items = append(items, item)
	}

	// Repo facts (stars, language, …) live in repo_facts keyed directly on the
	// repo group — resolve the rows' own ids to their facts in one batch
	// query, no placement resolution needed. Only mirrors with a landed facts
	// row match; everything else is simply absent. Best-effort: a lookup
	// failure leaves the facts panel empty rather than failing the read.
	factsByGroup := map[string]resource.RepoFacts{}
	if len(groupIDs) > 0 {
		if f, err := s.resource.RepoFactsByGroupIDs(ctx, groupIDs); err != nil {
			slogutil.Error(ctx, "backfill repo facts for repos list", slog.Any("error", err))
		} else {
			factsByGroup = f
		}
	}
	for i := range items {
		if f, ok := factsByGroup[items[i].ID]; ok {
			items[i].Facts = toAdminRepoFacts(f)
		}
	}

	// Batch-resolve display handles for the account-owned entire-forge rows
	// so the owner_name column can show a "provider:handle" rather than a raw
	// account ULID. The handle list is ordered is_primary DESC, so the first
	// entry is the primary.
	handlesByAccount := map[model.AccountID][]*model.Handle{}
	var accountIDs []model.AccountID
	seenAccount := map[string]bool{}
	for _, repo := range rows {
		if repo.Forge == resource.ForgeGitHub || repo.ProjectOwnerType != "account" || repo.OwnerAccountID == "" {
			continue
		}
		if seenAccount[repo.OwnerAccountID] {
			continue
		}
		seenAccount[repo.OwnerAccountID] = true
		accountIDs = append(accountIDs, model.AccountID(repo.OwnerAccountID))
	}
	if len(accountIDs) > 0 {
		if h, err := s.identity.ListHandlesForAccounts(ctx, accountIDs); err != nil {
			// Non-fatal: fall back to a blank owner_name for account-owned repos.
			slogutil.Error(ctx, "resolve owner handles for repos list", slog.Any("error", err))
		} else {
			handlesByAccount = h
		}
	}
	for i, repo := range rows {
		if repo.Forge != resource.ForgeGitHub && repo.ProjectOwnerType == "account" {
			items[i].OwnerName = primaryHandleString(handlesByAccount[model.AccountID(repo.OwnerAccountID)])
		}
	}
	return items, nil
}

// handleAdminGetRepoGroupRow is GET /api/admin/repo-groups/{groupID}: the
// admin repos listing's per-row shape (repoItem — project/org/visibility/
// facts/origin, the same enrichment handleAdminListRepos runs) for exactly
// one group. The admin console's ensureRepo calls this to fill in the fields
// a placement's own group-topology response can't carry (that query has no
// project/org/authz join) — so a drawer opened via a placement id (the
// Mirrors tab, an Orgs-drawer deep link, a nested placement click) gets the
// full record, not a thinner one.
func (s *Server) handleAdminGetRepoGroupRow(w http.ResponseWriter, r *http.Request) {
	if !s.requirePlatformAdminRead(w, r) {
		return
	}
	groupID, err := model.ParseRepoGroupID(r.PathValue("groupID"))
	if err != nil {
		http.Error(w, "bad request: invalid repo group ID", http.StatusBadRequest)
		return
	}
	row, err := s.resource.GetRepoGroupRow(r.Context(), groupID)
	if errors.Is(err, resource.ErrNotFound) {
		http.Error(w, "repo group not found", http.StatusNotFound)
		return
	}
	if err != nil {
		writeErr(w, r, http.StatusInternalServerError, err)
		return
	}
	items, err := s.enrichRepoItems(r.Context(), []*resource.RepoRow{row})
	if err != nil {
		writeErr(w, r, http.StatusInternalServerError, err)
		return
	}
	writeJSON(w, http.StatusOK, items[0])
}

// adminRepoFacts is the admin console's view of a repo's stored facts: the meta
// scalars plus the activity/prs facts and the meta provenance/audit fields, for
// the repo-detail pane. Unobserved fields stay null (omitempty) so the UI can
// show "—"; *time.Time renders as RFC3339 via encoding/json.
type adminRepoFacts struct {
	Stars           *int64     `json:"stars,omitempty"`
	Forks           *int64     `json:"forks,omitempty"`
	Language        *string    `json:"language,omitempty"`
	PushedAt        *time.Time `json:"pushed_at,omitempty"`
	Private         *bool      `json:"private,omitempty"`
	Archived        *bool      `json:"archived,omitempty"`
	CheckpointCount *int64     `json:"checkpoint_count,omitempty"`
	LastActivityAt  *time.Time `json:"last_activity_at,omitempty"`
	LastPushedAt    *time.Time `json:"last_pushed_at,omitempty"`
	ActivityHotness *float64   `json:"activity_hotness,omitempty"`
	OpenPRCount     *int64     `json:"open_pr_count,omitempty"`
	MetaSource      string     `json:"meta_source,omitempty"`
	MetaObservedAt  *time.Time `json:"meta_observed_at,omitempty"`
	PushSource      string     `json:"push_source,omitempty"`
	PushObservedAt  *time.Time `json:"push_observed_at,omitempty"`
	OriginCluster   string     `json:"origin_cluster,omitempty"`
}

func toAdminRepoFacts(f resource.RepoFacts) *adminRepoFacts {
	return &adminRepoFacts{
		Stars:           f.Stars,
		Forks:           f.Forks,
		Language:        f.Language,
		PushedAt:        f.PushedAt,
		Private:         f.Private,
		Archived:        f.Archived,
		CheckpointCount: f.CheckpointCount,
		LastActivityAt:  f.LastActivityAt,
		LastPushedAt:    f.LastPushedAt,
		ActivityHotness: f.ActivityHotness,
		OpenPRCount:     f.OpenPRCount,
		MetaSource:      f.MetaSource,
		MetaObservedAt:  f.MetaObservedAt,
		PushSource:      f.PushSource,
		PushObservedAt:  f.PushObservedAt,
		OriginCluster:   f.OriginCluster,
	}
}

// primaryHandleString renders the account's primary handle as "provider:handle"
// for the admin owner_name column. Handles are ordered is_primary DESC by
// ListHandlesForAccounts, so the first entry is the primary; returns "" when
// the account has no handle.
func primaryHandleString(handles []*model.Handle) string {
	if len(handles) == 0 {
		return ""
	}
	h := handles[0]
	return string(h.Provider) + ":" + h.Handle
}

