		fired := 0
		outcome, err := createAndAwaitMirror(ctx, c, "o", "r", "c", false, time.Second,
			func(*coreapi.CreatedMirror) { fired++ }, nil)
		require.Error(t, err)
		require.Nil(t, outcome.created)
		require.Zero(t, fired, "onCreated must not fire when create fails")
	})

