          "profileDataNote"
        ],
        "type": "object"
      },
      "WillUnlinkStruct": {
        "additionalProperties": true,
        "properties": {
          "grants": {
            "description": "Collaborator grants that will be unlinked.",
            "items": {
              "$ref": "#/components/schemas/DeletionGrant"
