	// Access/availability came from the entry's .Candidate). The two type
	// filters are mutually exclusive at the flag layer.
	if f.mirroredOnly {
		rows = slices.DeleteFunc(rows, func(r repoDirRow) bool { return len(r.Placements) == 0 })
