const cwd="/Users/pfleidi/entire/cli/.entire/worktrees/pfleidi-cor-1185-cli-submit-mirror-creates-through-the-async-mirror-request";
const cmds=[
"rg -n \"type MirrorRequest(Result|Succeeded|Status| struct)|CreatedMirror struct\" internal/coreapi -g '*.go'",
"rg -n -C 5 \"message MirrorRequest|MirrorRequestResult|mirror-requests|mirror_request\" openapi internal cmd -g '*.yaml' -g '*.json' -g '*.go'",
"sed -n '1,90p' cmd/entire/cli/config.go",
"rg -n -C 12 \"RequireEntireDir|repo\" cmd/entire/cli/root.go"
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:cwd,yield_time_ms:10000,max_output_tokens:10000})));
rs.forEach((r,i)=>{text(`--- ${i+1} exit ${r.exit_code} ---`);text(r.output)});

