const cwd="/Users/pfleidi/entire/cli/.entire/worktrees/pfleidi-cor-1185-cli-submit-mirror-creates-through-the-async-mirror-request";
const expected="cd1a56de5b94e6d95e976f57c70a0db1dd9a8163";
const [head,status,pr,requested,reviews,comments]=await Promise.all([
 tools.exec_command({cmd:"git log -1 --format=%H",workdir:cwd,yield_time_ms:10000,max_output_tokens:1000}),
 tools.exec_command({cmd:"git status --short",workdir:cwd,yield_time_ms:10000,max_output_tokens:2000}),
 tools.exec_command({cmd:"gh pr view 2207 --repo entireio/cli --json headRefOid",workdir:cwd,sandbox_permissions:"require_escalated",justification:"May I verify PR #2207’s head immediately before requesting fresh reviews?",prefix_rule:["gh","pr","view"],yield_time_ms:30000,max_output_tokens:2000}),
 tools.exec_command({cmd:"gh api repos/entireio/cli/pulls/2207/requested_reviewers",workdir:cwd,sandbox_permissions:"require_escalated",justification:"May I refresh requested reviewers before avoiding duplicate review requests?",prefix_rule:["gh","api"],yield_time_ms:30000,max_output_tokens:4000}),
 tools.exec_command({cmd:"gh api repos/entireio/cli/pulls/2207/reviews --paginate",workdir:cwd,sandbox_permissions:"require_escalated",justification:"May I refresh completed reviews before requesting fresh head coverage?",prefix_rule:["gh","api"],yield_time_ms:30000,max_output_tokens:12000}),
 tools.exec_command({cmd:"gh api repos/entireio/cli/issues/2207/comments --paginate",workdir:cwd,sandbox_permissions:"require_escalated",justification:"May I refresh Bugbot trigger state before requesting a fresh review?",prefix_rule:["gh","api"],yield_time_ms:30000,max_output_tokens:8000})
]);
text(`head=${head.output.trim()} status=${status.output.trim()||"(clean)"} pr=${pr.output.trim()}`);
text(`requested=${requested.output}`);
text(`reviews=${reviews.output}`);
text(`comments=${comments.output}`);
if(head.exit_code!==0||status.exit_code!==0||pr.exit_code!==0) exit();
const prData=JSON.parse(pr.output);
if(head.output.trim()!==expected||prData.headRefOid!==expected||status.output.trim()!==""){text("guard failed; no requests sent");exit();}
const [bugbot,copilot]=await Promise.all([
 tools.exec_command({
  cmd:"gh pr comment https://github.com/entireio/cli/pull/2207 --repo entireio/cli --body \"Bugbot run\"",
  workdir:cwd,sandbox_permissions:"require_escalated",
  justification:"May I request a fresh Bugbot review for the pushed COR-1185 head?",
  prefix_rule:["gh","pr","comment"],yield_time_ms:30000,max_output_tokens:4000
 }),
 tools.exec_command({
  cmd:"gh pr edit https://github.com/entireio/cli/pull/2207 --repo entireio/cli --add-reviewer @copilot",
  workdir:cwd,sandbox_permissions:"require_escalated",
  justification:"May I request a fresh Copilot review for the pushed COR-1185 head?",
  prefix_rule:["gh","pr","edit"],yield_time_ms:30000,max_output_tokens:4000
 })
]);
text(`bugbot exit ${bugbot.exit_code}: ${bugbot.output}`);
text(`copilot exit ${copilot.exit_code}: ${copilot.output}`);

const r=await tools.exec_command({
 cmd:"ENTIRE_CONTEXT=us.auth.entire.io entire trail watch 1195 --json",
 workdir:"/Users/pfleidi/entire/cli/.entire/worktrees/pfleidi-cor-1185-cli-submit-mirror-creates-through-the-async-mirror-request",
 sandbox_permissions:"require_escalated",
 justification:"May I watch trail 1195 with the coordinator-specified per-command context while the new review cycle runs?",
 yield_time_ms:1000,max_output_tokens:6000
});
text(JSON.stringify(r));

