+// newMirrorRequestClient serves handler from a test server for the test's
+// lifetime and returns a bearer-authenticated client pointed at it.
+func newMirrorRequestClient(t *testing.T, handler http.HandlerFunc) *coreapi.Client {
+	t.Helper()
+	srv := httptest.NewServer(handler)
+	t.Cleanup(srv.Close)
+	client, err := coreapi.NewWithBearer(srv.URL, "token")
+	require.NoError(t, err)
